1	import prisma from 'prisma/prisma';
2	import {
3	    GameDayWhereInputObjectSchema,
4	    GameDayWhereUniqueInputObjectSchema,
5	    TeamName,
6	} from 'prisma/zod/schemas';
7	import { GameDayType } from 'prisma/zod/schemas/models/GameDay.schema';
8	
9	import { isPrismaNotFoundError } from '@/lib/prismaErrors';
10	import {
11	    GameDayCreateOneStrictSchema,
12	    type GameDayUpdateInput,
13	    GameDayUpdateInputSchema,
14	    GameDayUpdateOneStrictSchema,
15	    type GameDayUpsertInput,
16	    GameDayUpsertInputSchema,
17	    GameDayUpsertOneStrictSchema,
18	    type GameDayWriteInput,
19	    GameDayWriteInputSchema,
20	} from '@/types/GameDayStrictSchema';
21	
22	class GameDayService {
23	    /**
24	     * Retrieves a GameDayWithOutcomesWithPlayers by its ID.
25	     * @param id - The ID of the GameDay to retrieve.
26	     * @returns A Promise that resolves to the GameDay object if found, or null
27	     * if not found.
28	     */
29	    async get(id: number): Promise<GameDayType | null> {
30	        const where = GameDayWhereUniqueInputObjectSchema.parse({ id });
31	        return prisma.gameDay.findUnique({ where });
32	    }
33	
34	    /**
35	     * Retrieves all game days based on the provided filters, sorted by date
36	     * ascending then ID ascending.
37	     *
38	     * @param {Object} filters - The filters to apply when retrieving game days.
39	     * @param {TeamNameType} [filters.bibs] - The team name or bibs to filter by. If "null", it will be treated as null.
40	     * @param {boolean} [filters.game] - Whether to filter by game status.
41	     * @param {boolean} [filters.mailSent] - Whether to filter by mail sent status. If true, it will filter for non-null mailSent values.
42	     * @param {number} [filters.year] - The year to filter by.
43	     * @param {Date} [filters.fromDate] - Only return game days on or after this date (inclusive).
44	     * @param {Date} [filters.beforeDate] - Only return game days before this date (exclusive).
45	     * @returns {Promise<GameDayType[]>} A promise that resolves to an array of GameDayType objects.
46	     */
47	    async getAll({
48	        bibs,
49	        game,
50	        mailSent,
51	        year,
52	        fromDate,
53	        beforeDate,
54	    }: {
55	        bibs?: TeamName;
56	        game?: boolean;
57	        mailSent?: boolean;
58	        year?: number;
59	        fromDate?: Date;
60	        beforeDate?: Date;
61	    } = {}): Promise<GameDayType[]> {
62	        const where = GameDayWhereInputObjectSchema.parse({
63	            bibs,
64	            game,
65	            year: year === 0 ? undefined : year,
66	        });
67	        if (mailSent !== undefined) {
68	            where.mailSent = mailSent ? { not: null } : null;
69	        }
70	        if (fromDate !== undefined || beforeDate !== undefined) {
71	            where.date = {
72	                ...(fromDate !== undefined ? { gte: fromDate } : {}),
73	                ...(beforeDate !== undefined ? { lt: beforeDate } : {}),
74	            };
75	        }
76	        return prisma.gameDay.findMany({
77	            where,
78	            orderBy: [{ date: 'asc' }, { id: 'asc' }],
79	        });
80	    }
81	
82	    /**
83	     * Retrieves the minimum and maximum GameDay IDs for a given year.
84	     *
85	     * @param year - The year to filter GameDays by. If `0` or negative, no date
86	     * filtering is applied and the range is calculated across all GameDays.
87	     * @returns A promise that resolves to an object containing `minId` and
88	     * `maxId` for the given year, or `null` if no matching GameDays are found.
89	     * @throws {Error} If the database query fails.
90	     */
91	    async getIdRangeForYear(year: number): Promise<{
92	        minId: number | null;
93	        maxId: number | null;
94	    }> {
95	        const result = await prisma.gameDay.aggregate({
96	            where: {
97	                ...(year > 0
98	                    ? {
99	                          date: {
100	                              gte: new Date(Date.UTC(year, 0, 1)),
101	                              lt: new Date(Date.UTC(year + 1, 0, 1)),
102	                          },
103	                      }
104	                    : undefined),
105	            },
106	            _min: { id: true },
107	            _max: { id: true },
108	        });
109	
110	        return { minId: result._min.id, maxId: result._max.id };
111	    }
112	
113	    /**
114	     * Retrieves a GameDayType object by the specified date.
115	     * @param date - The date to search for.
116	     * @returns A Promise that resolves to the GameDayType object if found, or null
117	     * if not found.
118	     */
119	    async getByDate(date: Date): Promise<GameDayType | null> {
120	        return prisma.gameDay.findFirst({ where: { date } });
121	    }
122	
123	    /**
124	     * Retrieves the current GameDayType: the most recent GameDayType where the mail has
125	     * been sent.
126	     * @returns A promise that resolves to the current GameDayType, or null if not found.
127	     */
128	    async getCurrent(): Promise<GameDayType | null> {
129	        const where = GameDayWhereInputObjectSchema.parse({
130	            mailSent: { not: null },
131	        });
132	        return prisma.gameDay.findFirst({ where, orderBy: { date: 'desc' } });
133	    }
134	
135	    /**
136	     * Retrieves the year of the current GameDayType (most recent with mail sent).
137	     * @returns A Promise that resolves to the year as a number, or null if no current game day exists.
138	     */
139	    async getCurrentYear(): Promise<number | null> {
140	        const currentGame = await this.getCurrent();
141	        return currentGame ? new Date(currentGame.date).getUTCFullYear() : null;
142	    }
143	
144	    /**
145	     * Retrieves the next upcoming GameDayType where a game is scheduled.
146	     * @param from - Optional date to compare against; defaults to now.
147	     */
148	    async getUpcoming(from: Date = new Date()): Promise<GameDayType | null> {
149	        const where = GameDayWhereInputObjectSchema.parse({
150	            game: true,
151	            date: { gte: from },
152	        });
153	        return prisma.gameDay.findFirst({ where, orderBy: { date: 'asc' } });
154	    }
155	
156	    /**
157	     * Retrieves the previous `GameDayType` based on the provided `gameDayId`.
158	     *
159	     * @param gameDayId - The ID of the current game day.
160	     * @returns A promise that resolves to the previous `GameDayType` or `null` if not found.
161	     */
162	    async getPrevious(gameDayId: number): Promise<GameDayType | null> {
163	        const currentGameDay = await this.get(gameDayId);
164	        if (!currentGameDay) return null;
165	
166	        const where = GameDayWhereInputObjectSchema.parse({
167	            date: { lt: currentGameDay.date },
168	        });
169	
170	        return prisma.gameDay.findFirst({ where, orderBy: { date: 'desc' } });
171	    }
172	
173	    /**
174	     * Retrieves the most recent GameDay record from the database.
175	     *
176	     * @returns A Promise that resolves to the latest GameDay object if found,
177	     * or null if no records exist.
178	     */
179	    async getLatest(): Promise<GameDayType | null> {
180	        return prisma.gameDay.findFirst({ orderBy: { id: 'desc' } });
181	    }
182	
183	    /**
184	     * Retrieves the next `GameDayType` that occurs after the specified game day.
185	     *
186	     * @param gameDayId - The unique identifier of the current game day.
187	     * @returns A promise that resolves to the next `GameDayType` if found, or `null` if there is none.
188	     */
189	    async getNext(gameDayId: number): Promise<GameDayType | null> {
190	        const currentGameDay = await this.get(gameDayId);
191	        if (!currentGameDay) return null;
192	
193	        const where = GameDayWhereInputObjectSchema.parse({
194	            date: { gt: currentGameDay.date },
195	        });
196	
197	        return prisma.gameDay.findFirst({ where, orderBy: { date: 'asc' } });
198	    }
199	
200	    /**
201	     * Retrieves the number of games played in the given year, optionally
202	     * stopping at a given gameDay ID.
203	     * @param year - The year to filter by, or zero for all years.
204	     * @param untilGameDayId - The gameDay ID to stop at (inclusive), or undefined.
205	     * @returns A promise that resolves to the number of games.
206	     */
207	    async getGamesPlayed(
208	        year: number,
209	        untilGameDayId?: number,
210	    ): Promise<number> {
211	        return prisma.gameDay.count({
212	            where: {
213	                game: true,
214	                ...(year !== 0
215	                    ? {
216	                          date: {
217	                              gte: new Date(Date.UTC(year, 0, 1)),
218	                              lt: new Date(Date.UTC(year + 1, 0, 1)),
219	                          },
220	                      }
221	                    : {}),
222	                ...(untilGameDayId
223	                    ? {
224	                          id: {
225	                              lte: untilGameDayId,
226	                          },
227	                      }
228	                    : {}),
229	            },
230	        });
231	    }
232	
233	    /**
234	     * Counts cancelled game days.
235	     *
236	     * A game day is considered cancelled when `game` is `false` and `mailSent`
237	     * is not `null`. Results can be filtered by calendar year and optionally
238	     * limited to game days up to a specific ID.
239	     *
240	     * @param year - The calendar year to filter by. If `0`, no year-based date
241	     * filter is applied.
242	     * @param untilGameDayId - Optional upper bound for game day IDs (inclusive).
243	     * @returns The number of matching cancelled game days.
244	     */
245	    async getGamesCancelled(
246	        year: number,
247	        untilGameDayId?: number,
248	    ): Promise<number> {
249	        return prisma.gameDay.count({
250	            where: {
251	                game: false,
252	                mailSent: { not: null },
253	                ...(year !== 0
254	                    ? {
255	                          date: {
256	                              gte: new Date(Date.UTC(year, 0, 1)),
257	                              lt: new Date(Date.UTC(year + 1, 0, 1)),
258	                          },
259	                      }
260	                    : {}),
261	                ...(untilGameDayId
262	                    ? {
263	                          id: {
264	                              lte: untilGameDayId,
265	                          },
266	                      }
267	                    : {}),
268	            },
269	        });
270	    }
271	
272	    /**
273	     * Retrieves the number of games yet to be played in the given year.
274	     * @param year - The year to filter by, or zero for all years.
275	     * @returns A promise that resolves to the number of games.
276	     */
277	    async getGamesRemaining(year: number): Promise<number> {
278	        return prisma.gameDay.count({
279	            where: {
280	                game: true,
281	                AND: [
282	                    {
283	                        ...(year !== 0
284	                            ? {
285	                                  date: {
286	                                      gte: new Date(Date.UTC(year, 0, 1)),
287	                                      lt: new Date(Date.UTC(year + 1, 0, 1)),
288	                                  },
289	                              }
290	                            : {}),
291	                    },
292	                    {
293	                        date: {
294	                            gt: new Date(),
295	                        },
296	                    },
297	                ],
298	            },
299	        });
300	    }
301	
302	    /**
303	     * Retrieves the IDs of the last game day for each season.
304	     *
305	     * @param until - Optional date to filter game days up to and including this
306	     * date
307	     * @returns A promise that resolves to an array of game day IDs representing
308	     * season enders, or null for seasons where no game day exists
309	     * @throws Will throw an error if the database query fails
310	     *
311	     * @example
312	     * ```typescript
313	     * // Get all season enders
314	     * const seasonEnders = await getSeasonEnders();
315	     *
316	     * // Get season enders up to a specific date
317	     * const seasonEnders = await getSeasonEnders(new Date('2023-12-31'));
318	     * ```
319	     */
320	    async getSeasonEnders(until?: Date): Promise<(number | null)[]> {
321	        const result = await prisma.gameDay.groupBy({
322	            by: ['year'],
323	            where: {
324	                game: true,
325	                ...(until
326	                    ? {
327	                          date: {
328	                              lte: until,
329	                          },
330	                      }
331	                    : {}),
332	            },
333	            _max: {
334	                id: true,
335	            },
336	        });
337	
338	        return result?.map((r) => r._max.id) ?? [];
339	    }
340	
341	    /**
342	     * Retrieves the list of distinct years that have at least one game day
343	     * marked as a game.
344	     *
345	     * Optionally includes `0` as a synthetic "All Time" year when
346	     * `includeAllTime` is `true`.
347	     *
