41	        if (
42	            dateDiff < 0 ||
43	            (dateDiff === 0 && a[i].gameDay!.id <= b[j].gameDay!.id)
44	        ) {
45	            result.push(a[i++]);
46	        } else {
47	            result.push(b[j++]);
