162	    /**
163	     * Retrieves the turnout for a specific game day or all game days.
164	     *
165	     * @param gameDayId - Optional. The ID of the game day to retrieve turnout for.
166	     * @returns An array of game days with their corresponding response counts.
167	     * @throws If there is an error fetching the outcomes.
168	     */
169	    async getTurnout(gameDayId?: number): Promise<Turnout[]> {
170	        const responseCounts = await this.getResponseCounts(gameDayId);
171	
172	        let gameDays = [];
173	        if (gameDayId === undefined) {
174	            gameDays = await gameDayService.getAll();
175	        } else {
176	            gameDays.push(await gameDayService.get(gameDayId));
177	        }
178	
179	        const result = gameDays.map((gameDay) => {
180	            const initialResponseCounts = new Map<string, number>([
181	                ['yes', 0],
182	                ['no', 0],
183	                ['dunno', 0],
184	                ['excused', 0],
185	                ['flaked', 0],
186	                ['injured', 0],
187	            ]);
188	            const gameDayResponseCounts = PlayerResponseSchema.options.reduce(
189	                (map, response) => {
190	                    const count =
191	                        responseCounts
192	                            .filter(
193	                                (res) =>
194	                                    res.gameDayId === gameDay?.id &&
195	                                    res.response === `${response}`,
196	                            )
197	                            .map((res) => res._count.response)[0] || 0;
198	                    map.set(`${response.toLowerCase()}`, count);
199	                    return map;
200	                },
201	                initialResponseCounts,
202	            );
203	
204	            if (gameDay) {
205	                return {
206	                    ...gameDay,
207	                    yes: gameDayResponseCounts.get('yes'),
208	                    no: gameDayResponseCounts.get('no'),
209	                    dunno: gameDayResponseCounts.get('dunno'),
210	                    excused: gameDayResponseCounts.get('excused'),
211	                    flaked: gameDayResponseCounts.get('flaked'),
212	                    injured: gameDayResponseCounts.get('injured'),
213	                    responses: responseCounts
214	                        .filter(
215	                            (rc) =>
216	                                rc.gameDayId === gameDay.id &&
217	                                rc.response !== null,
218	                        )
219	                        .reduce((acc, rc) => acc + rc._count.response, 0),
220	                    players:
221	                        responseCounts
222	                            .filter(
223	                                (rc) =>
224	                                    rc.gameDayId === gameDay.id &&
225	                                    rc.response ===
226	                                        PlayerResponseSchema.enum.Yes,
227	                            )
228	                            .map((rc) => rc._count.team)[0] || 0,
229	                    cancelled: gameDay.mailSent !== null && !gameDay.game,
230	                };
231	            }
232	        });
233	
234	        return result as Turnout[];
235	    }
