237	    /**
238	     * Retrieves the turnout data by year.
239	     * @returns A promise that resolves to an array of `TurnoutByYear` objects.
240	     * @throws If there is an error fetching the outcomes.
241	     */
242	    async getTurnoutByYear(): Promise<TurnoutByYearType[]> {
243	        const turnout = await this.getTurnout();
244	        const gameYears = await gameDayService.getAllYears({});
245	
246	        return gameYears.map((gameYear) => {
247	            const yearTurnout = turnout.filter((t) => gameYear === t.year);
248	            const result: TurnoutByYearType = {
249	                year: gameYear,
250	                gameDays: yearTurnout.length,
251	                gamesScheduled: yearTurnout.filter((t) => t.game || t.mailSent)
252	                    .length,
253	                gamesInitiated: yearTurnout.filter((t) => t.mailSent).length,
254	                gamesPlayed: yearTurnout.filter((t) => t.game && t.mailSent)
255	                    .length,
256	                gamesCancelled: yearTurnout.filter((t) => t.cancelled).length,
257	                responses: yearTurnout.reduce((acc, t) => acc + t.responses, 0),
258	                yesses: yearTurnout.reduce((acc, t) => acc + t.yes, 0),
259	                players: yearTurnout.reduce((acc, t) => acc + t.players, 0),
260	                responsesPerGameInitiated: 0,
261	                yessesPerGameInitiated: 0,
262	                playersPerGamePlayed: 0,
263	            };
264	
265	            if (result.gamesInitiated > 0) {
266	                result.responsesPerGameInitiated = parseFloat(
267	                    (result.responses / result.gamesInitiated).toFixed(1),
268	                );
269	                result.yessesPerGameInitiated = parseFloat(
270	                    (result.yesses / result.gamesInitiated).toFixed(1),
271	                );
272	            }
273	            if (result.gamesPlayed > 0) {
274	                result.playersPerGamePlayed = parseFloat(
275	                    (result.players / result.gamesPlayed).toFixed(1),
276	                );
277	            }
278	
279	            return result;
280	        });
281	    }
