355	    /**
356	     * Retrieves all players on a given team for a specific game day, including
357	     * their outcome for that day and their recent form.
358	     * @param gameDayId - The game day identifier.
359	     * @param team - Team to fetch ('A' or 'B').
360	     * @param formHistory - Number of previous games to include in each
361	     * player's form graph (default 5, minimum 0).
362	     *
363	     * Form behavior:
364	     * - Uses only prior outcomes with non-null points.
365	     * - Prior outcomes are returned oldest → newest.
366	     * - If fewer than formHistory outcomes exist, form is left-padded with
367	     *   unplayed sentinel entries (gameDayId: 0, points: null) so the result
368	     *   is always formHistory entries long.
369	     *
370	     * Sorting behavior:
371	     * - Players are ordered with goalies first.
372	     * - Within each group, players are ordered alphabetically by name.
373	     * @returns A promise resolving to the enriched player records.
374	     * @throws If there is an error fetching the data.
375	     */
376	    async getTeamPlayersByGameDay(
377	        gameDayId: number,
378	        team: TeamName,
379	        formHistory = 5,
380	    ): Promise<TeamPlayerType[]> {
381	        const validatedGameDayId = z.number().int().min(1).parse(gameDayId);
382	        const validatedTeam = TeamNameSchema.parse(team);
383	        const validatedHistory = z.number().int().min(0).parse(formHistory);
384	
385	        const outcomes = await prisma.outcome.findMany({
386	            where: {
387	                gameDayId: validatedGameDayId,
388	                team: validatedTeam,
389	            },
390	            include: {
391	                player: {
392	                    include: {
393	                        outcomes: {
394	                            where: {
395	                                gameDayId: { lt: validatedGameDayId },
396	                                points: { not: null },
397	                            },
398	                            orderBy: { gameDayId: 'desc' },
399	                            take: validatedHistory,
400	                            include: { gameDay: true },
401	                        },
402	                    },
403	                },
404	            },
405	            orderBy: [{ goalie: 'desc' }, { player: { name: 'asc' } }],
406	        });
407	
408	        return outcomes.map(({ player, ...outcome }) => {
409	            if (!player) {
410	                throw new InternalError(
411	                    `Outcome ${outcome.id} is missing its player relation.`,
412	                    {
413	                        details: {
414	                            outcomeId: outcome.id,
415	                            gameDayId: outcome.gameDayId,
416	                            playerId: outcome.playerId,
417	                            team: outcome.team,
418	                        },
419	                    },
420	                );
421	            }
422	            const { outcomes: playerOutcomes = [], ...playerData } = player;
423	
424	            // Outcomes arrive newest-first; reverse so the arc reads oldest→newest.
425	            const actualForm = [...playerOutcomes].reverse();
426	
427	            // Left-pad with unplayed sentinels for players newer than formHistory games.
428	            const paddingCount = Math.max(
429	                0,
430	                validatedHistory - actualForm.length,
431	            );
432	            const padding = Array.from({ length: paddingCount }, () => ({
433	                id: 0,
434	                gameDayId: 0,
435	                playerId: playerData.id,
436	                response: null,
437	                responseInterval: null,
438	                points: null,
439	                team: null,
440	                comment: null,
441	                pub: null,
442	                goalie: null,
443	            }));
444	
445	            return TeamPlayerSchema.parse({
446	                ...playerData,
447	                outcome,
448	                form: [...padding, ...actualForm],
449	            });
450	        });
451	    }
