467	    /**
468	     * Retrieves all outcomes for a player across a given year, or all time when
469	     * year is 0. Also includes game days where the player had no outcome
470	     * (not invited) and scheduled days where no game took place (game = false)
471	     * as synthetic entries with null points, so the result is suitable for
472	     * building a full activity heatmap with no gaps.
473	     *
474	     * @param playerId - The ID of the player.
475	     * @param year - The year to filter by, or 0 for all time.
476	     * @param fromDate - Optional earliest date (inclusive). Game days before
477	     * this date are excluded. Useful for filtering to a player's joined date.
478	     * @param toDate - Optional latest date (inclusive). Game days after this
479	     * date are excluded. Useful for filtering to a player's finished date.
480	     * @returns A promise that resolves to outcomes with game days, ordered by
481	     * game day date ascending, with game day ID as a tiebreaker. No-game days
482	     * and uninvited game days are represented as synthetic entries with
483	     * points = null; no-game days have gameDay.game = false.
484	     */
485	    async getHistoryByPlayer(
486	        playerId: number,
487	        year: number,
488	        fromDate?: Date,
489	        toDate?: Date,
490	    ): Promise<PlayerFormType[]> {
491	        const {
492	            playerId: pid,
493	            year: yr,
494	            fromDate: from,
495	            toDate: to,
496	        } = z
497	            .object({
498	                playerId: z.number().int().min(1),
499	                year: z.union([
500	                    z.literal(0),
501	                    z.number().int().min(1900).max(2100),
502	                ]),
503	                fromDate: z.date().optional(),
504	                toDate: z.date().optional(),
505	            })
506	            .parse({ playerId, year, fromDate, toDate });
507	
508	        // All day-boundary arithmetic uses UTC midnight so results are stable
509	        // across timezones and DST transitions.
510	        const utcDay = (y: number, m: number, d: number) =>
511	            new Date(Date.UTC(y, m, d));
512	        const utcDayOf = (date: Date) =>
513	            utcDay(
514	                date.getUTCFullYear(),
515	                date.getUTCMonth(),
516	                date.getUTCDate(),
517	            );
518	        const utcNextDayOf = (date: Date) =>
519	            utcDay(
520	                date.getUTCFullYear(),
521	                date.getUTCMonth(),
522	                date.getUTCDate() + 1,
523	            );
524	
525	        const yearStart = yr > 0 ? utcDay(yr, 0, 1) : undefined;
526	        // When both bounds are present, take the later start so neither is silently ignored.
527	        const startDate =
528	            yearStart && from
529	                ? new Date(
530	                      Math.max(yearStart.getTime(), utcDayOf(from).getTime()),
531	                  )
532	                : (yearStart ?? (from ? utcDayOf(from) : undefined));
533	        const yearEnd = yr > 0 ? utcDay(yr + 1, 0, 1) : undefined;
534	        // For toDate, convert the inclusive finished date to an exclusive upper bound (next UTC day),
535	        // then take the earliest of the year end, player finish, and tomorrow (no future game days).
536	        const finishedEnd = to ? utcNextDayOf(to) : undefined;
537	        const tomorrow = utcNextDayOf(new Date());
538	        const candidates = [yearEnd, finishedEnd, tomorrow].filter(
539	            (d): d is Date => d !== undefined,
540	        );
541	        const endDate = new Date(
542	            Math.min(...candidates.map((d) => d.getTime())),
543	        );
544	        // endDate is always defined: candidates always contains tomorrow.
545	        const dateRange: { gte?: Date; lt: Date } = { lt: endDate };
546	        if (startDate) dateRange.gte = startDate;
547	        const dateFilter = { date: dateRange };
548	
549	        const [outcomes, noGameDays, allGameDays] = await Promise.all([
550	            prisma.outcome.findMany({
551	                where: {
552	                    playerId: pid,
553	                    gameDay: { game: true, ...dateFilter },
554	                },
555	                orderBy: [{ gameDay: { date: 'asc' } }, { gameDayId: 'asc' }],
556	                include: { gameDay: true },
557	            }),
558	            gameDayService.getAll({
559	                game: false,
560	                fromDate: startDate,
561	                beforeDate: endDate,
562	            }),
563	            gameDayService.getAll({
564	                game: true,
565	                fromDate: startDate,
566	                beforeDate: endDate,
567	            }),
568	        ]);
569	
570	        const playedIds = new Set(outcomes.map((o) => o.gameDayId));
571	        const makeSynthetic = (
572	            gameDay: (typeof noGameDays)[number],
573	        ): PlayerFormType => ({
574	            id: -gameDay.id,
575	            gameDayId: gameDay.id,
576	            playerId: pid,
577	            response: null,
578	            responseInterval: null,
579	            points: null,
580	            team: null,
581	            comment: null,
582	            pub: null,
583	            goalie: null,
584	            gameDay,
585	        });
586	
587	        const synthetic: PlayerFormType[] = [
588	            ...noGameDays.map(makeSynthetic),
589	            ...allGameDays
590	                .filter((gd) => !playedIds.has(gd.id))
591	                .map(makeSynthetic),
592	        ];
593	
594	        return mergeByDate(outcomes, synthetic);
595	    }
