644	    /**
645	     * Calculates a player's recent average for picker logic using the legacy
646	     * PHP behavior:
647	     * - use recent game points before `gameDayId`
648	     * - include at most `history` rows from that list
649	     * - if fewer than `history` games exist, credit 1.45 points per missing game
650	     *
651	     * @param gameDayId - The current game day ID.
652	     * @param playerId - The player ID.
653	     * @param history - Number of recent games to consider.
654	     * @returns A promise resolving to the recent average.
655	     * @throws An error if there is a failure.
656	     */
657	    async getRecentAverage(
658	        gameDayId: number,
659	        playerId: number,
660	        history: number,
661	    ): Promise<number> {
662	        const parsed = z
663	            .object({
664	                gameDayId: z.number().int().min(1),
665	                playerId: z.number().int().min(1),
666	                history: z.number().int().min(1),
667	            })
668	            .parse({ gameDayId, playerId, history });
669	
670	        const points = await this.getRecentGamePoints(
671	            parsed.gameDayId,
672	            parsed.playerId,
673	        );
674	
675	        let total = 0;
676	        let count = 0;
677	        for (const point of points) {
678	            total += point ?? 0;
679	            count++;
680	            if (count === parsed.history) break;
681	        }
682	
683	        total += 1.45 * (parsed.history - count);
684	        return total / parsed.history;
685	    }
