import { readFileSync } from 'fs';

type GameDayRow = { id: number; game: boolean; mailSent: string | null };
type OutcomeRow = { gameDayId: number; team: 'A' | 'B' | null; points: number | null };

const gameDays: GameDayRow[] = JSON.parse(
    readFileSync('db-snapshot/GameDay.json', 'utf-8'),
);
const outcomes: OutcomeRow[] = JSON.parse(
    readFileSync('db-snapshot/Outcome.json', 'utf-8'),
);

const byGameDay = new Map<number, OutcomeRow[]>();
for (const o of outcomes) {
    if (!byGameDay.has(o.gameDayId)) byGameDay.set(o.gameDayId, []);
    byGameDay.get(o.gameDayId)!.push(o);
}

// Old logic: pickTeamPoints (unanimity check) + getGameWinnersFromTeams
function pickTeamPoints(rows: OutcomeRow[]): number | null {
    if (rows.length === 0) return null;
    const distinct = new Set<number>();
    for (const r of rows) {
        if (r.points !== 0 && r.points !== 1 && r.points !== 3) return null;
        distinct.add(r.points);
    }
    if (distinct.size !== 1) return null;
    return [...distinct][0];
}

function oldWinner(gameDayId: number): 'A' | 'B' | 'draw' | null {
    const rows = byGameDay.get(gameDayId) ?? [];
    const teamA = rows.filter((r) => r.team === 'A');
    const teamB = rows.filter((r) => r.team === 'B');
    const pointsA = pickTeamPoints(teamA);
    const pointsB = pickTeamPoints(teamB);
    if (pointsA === null || pointsB === null) return null;
    if (pointsA === 1 && pointsB === 1) return 'draw';
    if (pointsA === 3 && pointsB === 0) return 'A';
    if (pointsA === 0 && pointsB === 3) return 'B';
    return null;
}

// New backfill logic: MAX(points) per team
function newStatus(gameDay: GameDayRow): string {
    if (!gameDay.game) return 'NoGame';
    const rows = byGameDay.get(gameDay.id) ?? [];
    let aPoints: number | null = null;
    let bPoints: number | null = null;
    for (const r of rows) {
        if (r.team === 'A') aPoints = aPoints === null ? r.points : Math.max(aPoints, r.points ?? -Infinity);
        if (r.team === 'B') bPoints = bPoints === null ? r.points : Math.max(bPoints, r.points ?? -Infinity);
    }
    if (aPoints === 3 && bPoints === 0) return 'AWin';
    if (aPoints === 0 && bPoints === 3) return 'BWin';
    if (aPoints === 1 && bPoints === 1) return 'Draw';
    return 'Scheduled';
}

const winnerToStatus: Record<string, string> = {
    A: 'AWin',
    B: 'BWin',
    draw: 'Draw',
};

let mismatches = 0;
let noGameCount = 0;
let decidedCount = 0;
let scheduledCount = 0;
for (const gd of gameDays) {
    const status = newStatus(gd);
    if (status === 'NoGame') {
        noGameCount++;
        continue;
    }
    if (status === 'Scheduled') {
        scheduledCount++;
        continue;
    }
    decidedCount++;
    const expected = winnerToStatus[oldWinner(gd.id) ?? ''] ?? null;
    if (expected !== status) {
        mismatches++;
        if (mismatches <= 10) {
            console.log('MISMATCH', gd.id, { oldWinner: oldWinner(gd.id), newStatus: status });
        }
    }
}

console.log({
    totalGameDays: gameDays.length,
    noGameCount,
    scheduledCount,
    decidedCount,
    mismatches,
});
EOF
