/**
 * Retrieves all players on a given team for a specific game day, including
 * their outcome for that day and their recent form.
 * @param gameDayId - The game day identifier.
 * @param team - Team to fetch ('A' or 'B').
 * @param formHistory - Number of previous games to include in each
 * player's form graph (default 5, minimum 0).
 *
 * Form behavior:
 * - Uses only prior outcomes with non-null points.
 * - Prior outcomes are returned oldest → newest.
 * - If fewer than formHistory outcomes exist, form is left-padded with
 *   unplayed sentinel entries (gameDayId: 0, points: null) so the result
 *   is always formHistory entries long.
 *
 * Sorting behavior:
 * - Players are ordered with goalies first.
 * - Within each group, players are ordered alphabetically by name.
 * @returns A promise resolving to the enriched player records.
 * @throws If there is an error fetching the data.
 */
async getTeamPlayersByGameDay(
    gameDayId: number,
    team: TeamName,
    formHistory = 5,
): Promise<TeamPlayerType[]> {
    const validatedGameDayId = z.number().int().min(1).parse(gameDayId);
    const validatedTeam = TeamNameSchema.parse(team);
    const validatedHistory = z.number().int().min(0).parse(formHistory);

    const outcomes = await prisma.outcome.findMany({
        where: {
            gameDayId: validatedGameDayId,
            team: validatedTeam,
        },
        include: {
            player: {
                include: {
                    outcomes: {
                        where: {
                            gameDayId: { lt: validatedGameDayId },
                            points: { not: null },
                        },
                        orderBy: { gameDayId: 'desc' },
                        take: validatedHistory,
                        include: { gameDay: true },
                    },
                },
            },
        },
        orderBy: [{ goalie: 'desc' }, { player: { name: 'asc' } }],
    });

    return outcomes.map(({ player, ...outcome }) => {
        if (!player) {
            throw new InternalError(
                `Outcome ${outcome.id} is missing its player relation.`,
                {
                    details: {
                        outcomeId: outcome.id,
                        gameDayId: outcome.gameDayId,
                        playerId: outcome.playerId,
                        team: outcome.team,
                    },
                },
            );
        }
        const { outcomes: playerOutcomes = [], ...playerData } = player;

        // Outcomes arrive newest-first; reverse so the arc reads oldest→newest.
        const actualForm = [...playerOutcomes].reverse();

        // Left-pad with unplayed sentinels for players newer than formHistory games.
        const paddingCount = Math.max(
            0,
            validatedHistory - actualForm.length,
        );
        const padding = Array.from({ length: paddingCount }, () => ({
            id: 0,
            gameDayId: 0,
            playerId: playerData.id,
            response: null,
            responseInterval: null,
            points: null,
            team: null,
            comment: null,
            pub: null,
            goalie: null,
        }));

        return TeamPlayerSchema.parse({
            ...playerData,
            outcome,
            form: [...padding, ...actualForm],
        });
    });
}

