async getGamesPlayedByPlayer(
    playerId: number,
    year: number,
    untilGameDayId?: number,
): Promise<number> {
    return prisma.outcome.count({
        where: {
            playerId: playerId,
            points: {
                not: null,
            },
            gameDay: {
                ...(year !== 0
                    ? {
                          date: {
