                ...gameDayWhere,
            },
        };
    }
    if (points === 1) {
        return { gameDay: { status: 'Draw', ...gameDayWhere } };
    }

    const winningStatus: GameDayStatus = points === 3 ? 'AWin' : 'BWin';
    const losingStatus: GameDayStatus = points === 3 ? 'BWin' : 'AWin';

    return {
        OR: [
            {
                team: 'A',
                gameDay: { status: winningStatus, ...gameDayWhere },
            },
            {
                team: 'B',
                gameDay: { status: losingStatus, ...gameDayWhere },
