        new Date(b.gameDay!.date).getTime(),
);
entries.forEach((entry, i) => {
    cells.push({
        col,
        row: i + 1,
        points: entry.points ?? null,
        noGame: entry.gameDay!.game === false,
        date: new Date(entry.gameDay!.date),
        gameId: entry.gameDay!.id,
        comment: entry.gameDay?.comment,
    });
});

