// -------------------------------------------------------------------------
// Game days — one per week (Friday) for ~2 years, plus one upcoming game
// -------------------------------------------------------------------------
const now = new Date();
const gameDays: {
    id: number;
    year: number;
    date: Date;
    game: boolean;
    cost: number;
    hallCost: number;
    mailSent: Date | null;
}[] = [];

let gameDayId = 1;
// Start from the Friday ~2 years ago
let current = nextFriday(
    new Date(now.getFullYear() - 2, now.getMonth(), now.getDate()),
);

while (current < now) {
    // mailSent is set on historical games (Tuesday before the game) so that
    // getCurrent() (which requires mailSent IS NOT NULL) returns the most
    // recent past game — needed by the drinkers and responses admin pages.
    const mailSent = new Date(current);
    mailSent.setDate(mailSent.getDate() - 3); // Tuesday before the Friday game
    gameDays.push({
        id: gameDayId++,
        year: current.getFullYear(),
        date: new Date(current),
        game: true,
        cost: COST_PENCE,
        hallCost: HALL_COST_PENCE,
        mailSent,
    });
    current.setDate(current.getDate() + 7);
}

const upcomingGame = {
    id: gameDayId,
    year: nextFriday(now).getFullYear(),
    date: nextFriday(now),
    game: true,
    cost: COST_PENCE,
    hallCost: HALL_COST_PENCE,
    mailSent: null,
};
gameDays.push(upcomingGame);

await prisma.gameDay.createMany({ data: gameDays });
console.log(
    `  Created ${gameDays.length} game days (${gameDays.length - 1} historical + 1 upcoming)`,
);

// -------------------------------------------------------------------------
// Outcomes and transactions for historical games only
// (upcoming game has no outcomes so all players appear in the "none" group
//  on the responses admin page, which is what responses.spec.ts needs)
// -------------------------------------------------------------------------
const historicalGameDays = gameDays.slice(0, -1);
const outcomes: {
    gameDayId: number;
    playerId: number;
    response: PlayerResponse;
    team: TeamName;
    points: number;
    pub: number;
}[] = [];
const transactions: {
    type: TransactionType;
    amountPence: number;
    playerId: number | null;
    gameDayId: number;
}[] = [];

for (const gameDay of historicalGameDays) {
    // Pick 10–16 players at random for each game
    const shuffled = faker.helpers.shuffle([...players]);
    const count = faker.number.int({
        min: 10,
        max: Math.min(16, PLAYER_COUNT),
    });
    const playing = shuffled.slice(0, count);

    const half = Math.floor(count / 2);
    const teamAPlayers = playing.slice(0, half);
    const teamBPlayers = playing.slice(half);

    // 0 = A wins, 1 = draw, 2 = B wins
    const result = faker.number.int({ min: 0, max: 2 });
    const aPoints = result === 0 ? 3 : result === 1 ? 1 : 0;
    const bPoints = result === 2 ? 3 : result === 1 ? 1 : 0;

    for (const player of teamAPlayers) {
        outcomes.push({
            gameDayId: gameDay.id,
            playerId: player.id,
            response: PlayerResponse.Yes,
            team: TeamName.A,
            points: aPoints,
            pub: faker.datatype.boolean({ probability: 0.3 }) ? 1 : 0,
        });
        transactions.push({
            type: TransactionType.PlayerGameCharge,
            amountPence: COST_PENCE,
            playerId: player.id,
            gameDayId: gameDay.id,
        });
    }

    for (const player of teamBPlayers) {
        outcomes.push({
            gameDayId: gameDay.id,
            playerId: player.id,
            response: PlayerResponse.Yes,
            team: TeamName.B,
            points: bPoints,
            pub: faker.datatype.boolean({ probability: 0.3 }) ? 1 : 0,
        });
        transactions.push({
            type: TransactionType.PlayerGameCharge,
            amountPence: COST_PENCE,
            playerId: player.id,
            gameDayId: gameDay.id,
        });
    }

    // Hall hire transaction (no player)
    transactions.push({
        type: TransactionType.HallHire,
        amountPence: HALL_COST_PENCE,
        playerId: null,
        gameDayId: gameDay.id,
    });

