17	/**
18	 * Writes the data from a Prisma model to a JSON file.
19	 *
20	 * @param fileName - The name of the JSON file to be created.
21	 * @param prismaModel - The Prisma model object with a `findMany` method.
22	 * @returns A Promise that resolves when the JSON file is written.
23	 */
24	async function writeTableToJSONFile<T>(
25	    fileName: string,
26	    prismaModel: {
27	        findMany: () => Prisma.PrismaPromise<T[]>;
28	    },
29	) {
30	    console.log(`Writing ${fileName}...`);
31	    const data = await prismaModel.findMany();
32	    writeDataToJSONFile(fileName, data);
33	}
