35	interface PlayerExtraEmailSeed {
36	    playerId: number;
37	    email: string;
38	    verifiedAt?: Date | null;
39	}
40	
41	function writeDataToJSONFile<T>(fileName: string, data: T[]) {
42	    const json = JSON.stringify(data, null, 2);
43	    const filePath = path.join('/tmp/importlivedb', `${fileName}`);
44	    fs.writeFileSync(filePath, json);
45	}
46	
47	/**
48	 * Splits a comma-separated email string into a normalized list of emails.
49	 *
50	 * Normalization trims whitespace, removes empty entries, and lowercases all
51	 * email addresses.
52	 *
53	 * @param rawEmail - A comma-separated list of emails from legacy data.
54	 * @returns A normalized list of email addresses.
55	 */
56	function splitEmailList(rawEmail: string | null): string[] {
57	    if (!rawEmail) {
58	        return [];
59	    }
60	    return rawEmail
61	        .split(',')
62	        .map((email) => email.trim())
63	        .filter((email) => email.length > 0)
64	        .map((email) => email.toLowerCase());
65	}
66	
67	/**
68	 * Builds seed data for `account.email` and `playerExtraEmail` from legacy
69	 * player email values.
70	 *
71	 * The first unique email is treated as the account email and any remaining
72	 * unique emails are emitted as extra email rows. Duplicate emails already
73	 * assigned to another player are skipped.
74	 *
75	 * @param sources - Player IDs and raw legacy email strings.
76	 * @returns A map of primary account emails keyed by player ID and extra email
77	 * rows for seeding.
78	 */
79	function buildPlayerEmailSeeds(
80	    sources: { playerId: number; email: string | null }[],
81	): {
82	    accountEmailByPlayerId: Map<number, string>;
83	    extraEmailRows: PlayerExtraEmailSeed[];
84	} {
85	    const extraEmailRows: PlayerExtraEmailSeed[] = [];
86	    const accountEmailByPlayerId = new Map<number, string>();
87	    const seen = new Map<string, number>();
88	
89	    sources.forEach((source) => {
90	        const emails = Array.from(new Set(splitEmailList(source.email)));
91	        if (emails.length === 0) return;
92	
93	        const [accountEmail, ...extraEmails] = emails;
94	
95	        if (accountEmail) {
96	            const existing = seen.get(accountEmail);
97	            if (existing && existing !== source.playerId) {
98	                console.warn(
99	                    `Skipping duplicate account email ${accountEmail} for player ${source.playerId}; already assigned to player ${existing}`,
100	                );
101	            } else {
102	                seen.set(accountEmail, source.playerId);
103	                accountEmailByPlayerId.set(source.playerId, accountEmail);
104	            }
105	        }
106	
107	        extraEmails.forEach((email) => {
108	            const existing = seen.get(email);
109	            if (existing && existing !== source.playerId) {
110	                console.warn(
111	                    `Skipping duplicate extra email ${email} for player ${source.playerId}; already assigned to player ${existing}`,
112	                );
113	                return;
114	            }
115	
116	            seen.set(email, source.playerId);
117	            extraEmailRows.push({
118	                playerId: source.playerId,
119	                email,
120	            });
121	        });
122	    });
123	
124	    return { accountEmailByPlayerId, extraEmailRows };
125	}
126	
127	/**
128	 * Corrects `player.joined`/`player.finished` dates that are inconsistent with
129	 * the player's actual game history, e.g. a `joined` date that falls after the
130	 * date of a game the player has an outcome for. Such inconsistencies have been
131	 * seen in the legacy data (manually entered by league admins over many years)
132	 * and cause players to be silently excluded from parts of their own game
133	 * history — for example the profile heatmap, which bounds its date range by
134	 * `joined`/`finished`.
135	 *
136	 * Widens `joined` back to (or `finished` forward to) the earliest/latest game
137	 * day the player has an outcome for, logging a warning for every correction
138	 * made so it can be reviewed.
139	 *
140	 * @returns A promise that resolves once all inconsistent players have been
141	 * corrected.
142	 */
143	async function reconcilePlayerJoinedFinishedDates(): Promise<void> {
144	    console.log(
145	        'Reconciling player joined/finished dates against actual game history...',
146	    );
147	
148	    const outcomes = await prisma.outcome.findMany({
149	        where: { gameDay: { status: { not: 'NoGame' } } },
150	        select: { playerId: true, gameDay: { select: { date: true } } },
151	    });
152	
153	    const rangeByPlayer = new Map<number, { min: Date; max: Date }>();
154	    for (const {
155	        playerId,
156	        gameDay: { date },
157	    } of outcomes) {
158	        const existing = rangeByPlayer.get(playerId);
159	        if (!existing) {
160	            rangeByPlayer.set(playerId, { min: date, max: date });
161	        } else {
162	            if (date < existing.min) existing.min = date;
163	            if (date > existing.max) existing.max = date;
164	        }
165	    }
166	
167	    const players = await prisma.player.findMany({
168	        where: { id: { in: Array.from(rangeByPlayer.keys()) } },
169	        select: { id: true, joined: true, finished: true },
170	    });
171	
172	    for (const player of players) {
173	        const range = rangeByPlayer.get(player.id)!;
174	        const data: { joined?: Date; finished?: Date } = {};
175	
176	        if (player.joined && player.joined > range.min) {
177	            console.warn(
178	                `Player ${player.id}: joined date ${player.joined.toISOString()} is after their earliest recorded game (${range.min.toISOString()}); correcting.`,
179	            );
180	            data.joined = range.min;
181	        }
182	        if (player.finished && player.finished < range.max) {
183	            console.warn(
184	                `Player ${player.id}: finished date ${player.finished.toISOString()} is before their latest recorded game (${range.max.toISOString()}); correcting.`,
185	            );
186	            data.finished = range.max;
187	        }
188	
189	        if (Object.keys(data).length > 0) {
190	            await prisma.player.update({ where: { id: player.id }, data });
191	        }
192	    }
193	}
194	
195	async function fetchLegacyPlayerEmailSources(): Promise<
196	    { playerId: number; email: string | null }[]
197	> {
198	    // The raw query here is OK because this is a temporary script and there is no user input
199	    const rows = await prisma.$queryRawUnsafe<
200	        { id: number; email: string | null }[]
201	    >('SELECT id, email FROM player');
202	
203	    return rows.map((row) => ({
204	        playerId: row.id,
205	        email: row.email ?? null,
206	    }));
207	}
208	
209	/**
210	 * Imports a MySQL backup file and runs migrations to set up the database
211	 * structure. This is to support a non-standard workflow where the database is
212	 * backed up from a live server and imported into a local development
213	 * environment, and then all but the 'init' migration are run to make the
214	 * development database match the current development schema. This means I can
215	 * carry on developing the new website while new data is being added to the old
216	 * one, and then switch over when I'm ready.
217	 * @returns {Promise<void>} - A promise that resolves when the import and
218	 * migrations are completed.
219	 */
220	async function importBackup(): Promise<void> {
221	    try {
222	        // Get all MYSQL environment variables
223	        if (!process.env.IMP_PROD_MYSQL_USER) {
224	            throw new Error('IMP_PROD_MYSQL_USER undefined');
225	        }
226	        if (!process.env.IMP_PROD_MYSQL_HOST) {
227	            throw new Error('IMP_PROD_MYSQL_HOST undefined');
228	        }
229	        if (!process.env.IMP_PROD_MYSQL_PORT) {
230	            throw new Error('IMP_PROD_MYSQL_PORT undefined');
231	        }
232	        if (!process.env.IMP_PROD_MYSQL_PASSWORD) {
233	            throw new Error('IMP_PROD_MYSQL_PASSWORD undefined');
234	        }
235	
236	        if (!process.env.IMP_DEV_MYSQL_USER) {
237	            throw new Error('IMP_DEV_MYSQL_USER undefined');
238	        }
239	        if (!process.env.IMP_DEV_MYSQL_HOST) {
240	            throw new Error('IMP_DEV_MYSQL_HOST undefined');
241	        }
242	        if (!process.env.IMP_DEV_MYSQL_PORT) {
243	            throw new Error('IMP_DEV_MYSQL_PORT undefined');
244	        }
245	        if (!process.env.IMP_DEV_MYSQL_PASSWORD) {
246	            throw new Error('IMP_DEV_MYSQL_PASSWORD undefined');
247	        }
248	
249	        if (!process.env.IMP_AZURE_TENANT_ID) {
250	            throw new Error('IMP_AZURE_TENANT_ID undefined');
251	        }
252	        if (!process.env.IMP_AZURE_CLIENT_ID) {
253	            throw new Error('IMP_AZURE_CLIENT_ID undefined');
254	        }
255	        if (!process.env.IMP_AZURE_CLIENT_SECRET) {
256	            throw new Error('IMP_AZURE_CLIENT_SECRET undefined');
257	        }
258	
259	        const prodMysqlUser = process.env.IMP_PROD_MYSQL_USER;
260	        const prodMysqlHost = process.env.IMP_PROD_MYSQL_HOST;
261	        const prodMysqlPort = process.env.IMP_PROD_MYSQL_PORT;
262	        const prodMysqlPassword = process.env.IMP_PROD_MYSQL_PASSWORD;
263	
264	        const devMysqlUser = process.env.IMP_DEV_MYSQL_USER;
265	        const devMysqlHost = process.env.IMP_DEV_MYSQL_HOST;
266	        const devMysqlPort = process.env.IMP_DEV_MYSQL_PORT;
267	        const devMysqlPassword = process.env.IMP_DEV_MYSQL_PASSWORD;
268	
269	        const mysqlDatabase = 'footy';
270	
271	        const tenantId = process.env.IMP_AZURE_TENANT_ID;
272	
273	        const clientId = process.env.IMP_AZURE_CLIENT_ID;
274	        const clientSecret = process.env.IMP_AZURE_CLIENT_SECRET;
275	
276	        const storageAccountName = 'nextwwwtoastboy';
277	        const containerName = 'dbseeddata';
278	
279	        const credentials = new ClientSecretCredential(
280	            tenantId,
281	            clientId,
282	            clientSecret,
283	        );
284	        const blobServiceClient = new BlobServiceClient(
285	            `https://${storageAccountName}.blob.core.windows.net`,
286	            credentials,
287	        );
288	
289	        const containerClient =
290	            blobServiceClient.getContainerClient(containerName);
291	
292	        const shellExec = (cmd: string) => {
293	            execSync(cmd, { stdio: 'inherit' });
294	        };
295	
296	        // Take a backup of the current live database
297	        console.log('Taking production mysql backup...');
298	        shellExec(
299	            `mysqldump --skip-ssl -h ${prodMysqlHost} -P ${prodMysqlPort} -u ${prodMysqlUser} -p${prodMysqlPassword} ${mysqlDatabase} arse club club_supporter country diffs game_chat game_day invitation misc nationality outcome picker picker_teams player > /tmp/${mysqlDatabase}.sql`,
300	        );
301	
302	        // Get the list of directories in the migrations directory
303	        const migrationsDir = path.join(
304	            currentDir,
305	            '..',
306	            '..',
307	            '..',
308	            'prisma',
309	            'migrations',
310	        );
311	        const migrations = await readdir(migrationsDir);
312	
313	        // Run prisma generate to ensure the Prisma Client is up to date
314	        console.log('Running prisma generate...');
315	        shellExec('npx prisma generate --schema prisma/schema.prisma');
316	
317	        // Run prisma db push to ensure the database is up to date with the schema
318	        console.log('Running prisma db push...');
319	        shellExec(
320	            `mysql --skip-ssl -h ${devMysqlHost} -P ${devMysqlPort} -u ${devMysqlUser} -p${devMysqlPassword} -e'DROP DATABASE IF EXISTS footy;'`,
321	        );
322	        shellExec(
323	            `mysql --skip-ssl -h ${devMysqlHost} -P ${devMysqlPort} -u ${devMysqlUser} -p${devMysqlPassword} -e'CREATE DATABASE footy;'`,
324	        );
325	        shellExec(
326	            'npx prisma db push --accept-data-loss --schema prisma/schema.prisma',
327	        );
328	
329	        // Import the mysqldump backup created above
330	        console.log('Importing mysql backup...');
331	        shellExec(
332	            `cat /tmp/${mysqlDatabase}.sql | mysql --skip-ssl -h ${devMysqlHost} -P ${devMysqlPort} -u ${devMysqlUser} -p${devMysqlPassword} ${mysqlDatabase}`,
333	        );
334	
335	        const legacyPlayerEmailSources = await fetchLegacyPlayerEmailSources();
336	
337	        // Run each migration except the first one: the backup created the
338	        // database structure through the conditional comments such as '/*!40000
339	        // DROP DATABASE IF EXISTS `footy`*/;'
340	        for (let i = 1; i < migrations.length; i++) {
341	            if (migrations[i].endsWith('migration_lock.toml')) {
342	                continue;
343	            }
344	            console.log(`Running migration ${migrations[i]}...`);
345	            const migration = path.join(
346	                migrationsDir,
347	                migrations[i],
348	                'migration.sql',
349	            );
350	            shellExec(
351	                `cat ${migration} | mysql --skip-ssl -h ${devMysqlHost} -P ${devMysqlPort} -u ${devMysqlUser} -p${devMysqlPassword} ${mysqlDatabase}`,
352	            );
353	        }
354	
355	        // Run prisma generate again to take account of any schema changes during migrations
356	        console.log('Running prisma generate again...');
357	        shellExec('npx prisma generate --schema prisma/schema.prisma');
358	
359	        const { accountEmailByPlayerId, extraEmailRows } =
360	            buildPlayerEmailSeeds(legacyPlayerEmailSources);
361	
362	        for (const [
363	            playerId,
364	            accountEmail,
365	        ] of accountEmailByPlayerId.entries()) {
366	            await prisma.player.update({
367	                where: { id: playerId },
368	                data: { accountEmail },
369	            });
370	        }
371	
372	        await reconcilePlayerJoinedFinishedDates();
373	
374	        // Calculate player records from the migrated outcome data before the
375	        // reset so they can be included in the blob export and restored by
376	        // seed.ts without recalculation.
377	        console.log('Calculating player records...');
378	        await playerRecordService.deleteAll();
379	        await playerRecordService.upsertForGameDay();
380	
381	        // Write each table in ${mysqlDatabase} to a JSON file in /tmp/importlivedb
382	        console.log('Writing tables to JSON files...');
383	        shellExec(`mkdir -p /tmp/importlivedb`);
384	        for (const { fileName, getModel } of GAME_DATA_TABLES.filter(
385	            (e) => e.fileName !== 'PlayerEmail.json',
386	        )) {
387	            await writeTableToJSONFile(
388	                fileName,
389	                getModel(prisma) as {
390	                    findMany: () => Prisma.PrismaPromise<object[]>;
391	                },
392	            );
393	        }
394	
395	        writeDataToJSONFile('PlayerEmail.json', extraEmailRows);
396	
397	        // Upload the JSON files to Azure Blob Storage
398	        const files = await readdir('/tmp/importlivedb');
399	        for (const file of files) {
400	            console.log(`Uploading ${file}...`);
401	            const filePath = path.join('/tmp/importlivedb', file);
402	            const blockBlobClient = containerClient.getBlockBlobClient(file);
403	            await blockBlobClient.uploadFile(filePath);
404	        }
405	        shellExec('rm -rf /tmp/importlivedb');
406	
407	        // Capture any player accounts that were claimed since the last run so
408	        // they survive the database reset below. Without this, repeated calls
409	        // to importlivedb would silently destroy claimed accounts.
410	        console.log('Capturing current Better Auth state before reset...');
411	        await exportAuthTables(containerClient);
412	
413	        // Now the dev database is up to date with the live one and the seed
414	        // files in blob storage reflect that, do a final reset/migrate and then
415	        // run seeding explicitly.
416	        console.log('Running final Prisma migrate reset...');
417	        shellExec('npx prisma migrate reset --force');
418	        console.log('Running final Prisma db seed...');
419	        shellExec('npx prisma db seed');
420	    } catch (error) {
421	        console.error('An error occurred:', error);
422	        throw error;
423	    }
424	}
425	
426	void importBackup()
427	    .catch((error) => {
428	        console.error('An unexpected error occurred:', error);
429	    })
430	    .finally(async () => {
431	        await prisma.$disconnect();
432	    });
433	
434	// To run: `op run --env-file ./src/lib/importlivedb/.env -- sh -c 'npm run importlivedb'`
435

