11	import { type PlayerFormType } from '@/types';
12	
13	import styles from './PlayerHeatmap.module.css';
14	
15	export interface Props {
16	    /**
17	     * Outcomes to visualise. Every entry must have a populated `gameDay`
18	     * (including a native `Date` object for `gameDay.date` — Prisma returns
19	     * `Date`, but JSON-serialised props will have a string and will not render
20	     * correctly). Entries whose `gameDay.status` is `NoGame` represent
21	     * scheduled days on which no game took place; they are shown in light
22	     * grey and navigate to the game day details page on click. Entries with
23	     * `points === null` and `status !== 'NoGame'` represent days the player
24	     * was invited but did not play.
25	     */
26	    data: PlayerFormType[];
27	    /**
28	     * The calendar year being displayed, or `0` for the all-time view.
29	     *
30	     * - When `year > 0` the chart renders a single panel with months (Jan–Dec)
31	     *   on the X axis and game-number-within-month on the Y axis.
32	     * - When `year === 0` year panels are laid out side by side, wrapping to
33	     *   the next row when the viewport width is exhausted, most recent year first.
34	     */
35	    year: number;
36	}
37	
38	interface Cell {
39	    col: string;
40	    row: number;
41	    points: number | null | undefined;
42	    noGame: boolean;
43	    date: Date;
44	    gameId: number;
45	    comment: string | null | undefined;
46	}
47	
48	const colorMap = new Map<number | null | undefined, string>([
49	    [null, 'var(--mantine-color-gray-5)'],
50	    [undefined, 'var(--mantine-color-gray-5)'],
51	    [0, 'var(--mantine-color-red-6)'],
52	    [1, 'var(--mantine-color-yellow-5)'],
53	    [3, 'var(--mantine-color-green-6)'],
54	]);
55	
56	const NO_GAME_COLOR = 'var(--mantine-color-gray-3)';
57	
58	const resultLabel = new Map<number | null | undefined, string>([
59	    [null, 'Did not play'],
60	    [undefined, 'Did not play'],
61	    [0, 'Lost'],
62	    [1, 'Drew'],
63	    [3, 'Won'],
64	]);
65	
66	// Short names are the unique domain keys; narrow names are used for axis display.
67	const MONTH_COLS = Array.from({ length: 12 }, (_, i) =>
68	    getShortMonthName(2000, i + 1),
69	);
70	const SHORT_TO_NARROW = new Map(
71	    MONTH_COLS.map((short, i) => [short, getNarrowMonthName(2000, i + 1)]),
72	);
73	
74	/** Builds the flat cell list for a single year's data (always month columns). */
75	export function buildGrid(data: PlayerFormType[]): {
76	    cells: Cell[];
77	    maxRow: number;
78	} {
79	    const grouped = new Map<string, PlayerFormType[]>();
80	
81	    for (const entry of data) {
82	        if (!entry.gameDay) continue;
83	        const date = new Date(entry.gameDay.date);
84	        const col = getShortMonthName(date.getFullYear(), date.getMonth() + 1);
85	        const list = grouped.get(col) ?? [];
86	        list.push(entry);
87	        grouped.set(col, list);
88	    }
89	
90	    const cells: Cell[] = [];
91	    let maxRow = 0;
92	
93	    for (const col of MONTH_COLS) {
94	        const entries = (grouped.get(col) ?? []).sort(
95	            (a, b) =>
96	                new Date(a.gameDay!.date).getTime() -
97	                new Date(b.gameDay!.date).getTime(),
98	        );
99	        entries.forEach((entry, i) => {
100	            cells.push({
101	                col,
102	                row: i + 1,
103	                points: entry.points ?? null,
104	                noGame: entry.gameDay!.status === 'NoGame',
105	                date: new Date(entry.gameDay!.date),
106	                gameId: entry.gameDay!.id,
107	                comment: entry.gameDay?.comment,
108	            });
109	        });
110	        maxRow = Math.max(maxRow, entries.length);
111	    }
112	
113	    return { cells, maxRow };
114	}
115	
116	/**
117	 * Groups data by year, builds a cell list for each year, and returns an array of year groups
118	 * sorted in reverse chronological order.
119	 */
120	export function buildYearGroups(
121	    data: PlayerFormType[],
122	): { year: string; cells: Cell[]; maxRow: number }[] {
123	    const byYear = new Map<string, PlayerFormType[]>();
124	    for (const entry of data) {
125	        if (!entry.gameDay) continue;
126	        const yr = String(new Date(entry.gameDay.date).getFullYear());
127	        const list = byYear.get(yr) ?? [];
128	        list.push(entry);
129	        byYear.set(yr, list);
130	    }
131	    return Array.from(byYear.keys())
132	        .sort((a, b) => Number(b) - Number(a))
133	        .map((yr) => ({ year: yr, ...buildGrid(byYear.get(yr)!) }));
134	}
135	
136	const GAP = 2;
137	const CELL_SIZE = 10;
138	const M = { top: 4, right: 10, bottom: 24, left: 4 };
139	const YEAR_LABEL_HEIGHT = 22;
140	
141	interface TooltipContent {
142	    date: string;
143	    label: string;
144	    comment?: string | null;
145	}
146	
147	type ShowTooltip = (
148	    event: globalThis.MouseEvent,
149	    content: TooltipContent,
150	) => void;
151	
152	/**
153	 * Returns an X scale for the month columns, along with the calculated inner
154	 * width (excluding margins) needed to fit the columns at the specified cell
155	 * size and gap. The scale's domain is the short month names (e.g., "Jan",
156	 * "Feb") and its range is [0, innerWidth]. The scale's bandwidth is the cell
157	 * size, and its paddingInner is set to create the specified gap between cells.
158	 * The caller can use the returned inner width to set the SVG width and the
159	 * scale to position cells and axis ticks.
160	 *
161	 * @returns An object containing the configured X scale and the calculated inner
162	 * width.
163	 */
164	function makeXScale(): { scale: ScaleBand<string>; iw: number } {
165	    const n = MONTH_COLS.length;
166	    const iw = n * CELL_SIZE + (n - 1) * GAP;
167	    const paddingInner = GAP / (CELL_SIZE + GAP);
168	    const scale = scaleBand()
169	        .domain(MONTH_COLS)
170	        .range([0, iw])
171	        .paddingInner(paddingInner);
172	    return { scale, iw };
173	}
174	
175	function drawPanel(
176	    g: Selection<SVGGElement, unknown, null, undefined>,
177	    cells: Cell[],
178	    maxRow: number,
179	    xScale: ScaleBand<string>,
180	    showTooltip: ShowTooltip,
181	    hideTooltip: () => void,
182	    onCellClick: (gameId: number) => void,
183	) {
184	    const cellSize = xScale.bandwidth();
185	    const ih = maxRow * cellSize + Math.max(0, maxRow - 1) * GAP;
186	
187	    // X axis — domain keys are short names; labels are rendered as narrow single letters
188	    g.append('g')
189	        .attr('transform', `translate(0,${ih + 4})`)
190	        .call(
191	            axisBottom(xScale)
192	                .tickSize(0)
193	                .tickFormat((d) => SHORT_TO_NARROW.get(d)!),
194	        )
195	        .call((ax) => {
196	            ax.select('.domain').remove();
197	        });
198	
199	    // Cells
200	    g.selectAll<SVGRectElement, Cell>('rect.cell')
201	        .data(cells)
202	        .enter()
203	        .append('rect')
204	        .attr('class', 'cell')
205	        .attr('x', (d) => xScale(d.col)!)
206	        .attr('y', (d) => (d.row - 1) * (cellSize + GAP))
207	        .attr('width', xScale.bandwidth())
208	        .attr('height', cellSize)
209	        .attr('rx', 2)
210	        .attr('role', 'button')
211	        .attr('tabindex', '0')
212	        .attr('aria-label', (d) => {
213	            if (d.noGame) {
214	                const status = d.comment ? `No game — ${d.comment}` : 'No game';
215	                return `${formatDate(d.date)} – ${status}`;
216	            }
217	            return `${formatDate(d.date)} – ${resultLabel.get(d.points) ?? ''}`;
218	        })
219	        .style('fill', (d) =>
220	            d.noGame
221	                ? NO_GAME_COLOR
222	                : (colorMap.get(d.points) ?? 'var(--mantine-color-gray-5)'),
223	        )
224	        .style('cursor', 'pointer')
225	        .on('mousemove', (event: globalThis.MouseEvent, d) => {
226	            showTooltip(event, {
227	                date: formatDate(d.date),
228	                label: d.noGame ? 'No game' : (resultLabel.get(d.points) ?? ''),
229	                comment: d.noGame ? d.comment : undefined,
230	            });
231	        })
232	        .on('mouseleave', hideTooltip)
233	        .on('click', (_, d) => {
234	            onCellClick(d.gameId);
235	        })
236	        .on('keydown', (event: globalThis.KeyboardEvent, d) => {
237	            if (event.key === 'Enter' || event.key === ' ') {
238	                event.preventDefault();
239	                onCellClick(d.gameId);
240	            }
241	        });
242	}
243	
244	interface YearPanelProps {
245	    label: string;
246	    cells: Cell[];
247	    globalMaxRow: number;
248	    showTooltip: ShowTooltip;
249	    hideTooltip: () => void;
250	}
251	
252	/**
253	 * Renders a panel for a single year in the player's heatmap.
254	 *
255	 * @param props - See {@link YearPanelProps}.
256	 */
257	const YearPanel = ({
258	    label,
259	    cells,
260	    globalMaxRow,
261	    showTooltip,
262	    hideTooltip,
263	}: YearPanelProps) => {
264	    const svgRef = useRef<SVGSVGElement>(null);
265	    const router = useRouter();
266	
267	    useEffect(() => {
268	        /* c8 ignore next */
269	        if (!svgRef.current) return;
270	        const onCellClick = (gameId: number) =>
271	            router.push(`/footy/game/${gameId}`);
272	        const { scale: xScale, iw } = makeXScale();
273	        const cellSize = xScale.bandwidth();
274	        const ih =
275	            globalMaxRow * cellSize + Math.max(0, globalMaxRow - 1) * GAP;
276	        const w = iw + M.left + M.right;
277	        const h = YEAR_LABEL_HEIGHT + M.top + ih + M.bottom;
278	
279	        const svg = select(svgRef.current);
280	        svg.selectAll('*').remove();
281	        svg.attr('width', w).attr('height', h);
282	
283	        svg.append('text')
284	            .attr('x', M.left)
285	            .attr('y', YEAR_LABEL_HEIGHT - 4)
286	            .style('font-size', '14px')
287	            .style('font-weight', '600')
288	            .style('fill', 'currentColor')
289	            .text(label);
290	
291	        const g = svg
292	            .append('g')
293	            .attr(
294	                'transform',
295	                `translate(${M.left},${YEAR_LABEL_HEIGHT + M.top})`,
296	            );
297	        drawPanel(
298	            g,
299	            cells,
300	            globalMaxRow,
301	            xScale,
302	            showTooltip,
303	            hideTooltip,
304	            onCellClick,
305	        );
306	    }, [cells, globalMaxRow, hideTooltip, label, router, showTooltip]);
307	
308	    return <svg ref={svgRef} />;
309	};
310	
311	/**
312	 * Renders a D3 heatmap of a player's game history.
313	 *
314	 * Each cell represents one game day, coloured by result:
315	 * - Green  — won (points = 3)
316	 * - Yellow — draw (points = 1)
317	 * - Grey   — invited but did not play (points = null, status != NoGame)
318	 * - Red    — lost (points = 0)
319	 * - Light grey — no game took place (gameDay.status = NoGame)
320	 *
321	 * Clicking or pressing Enter/Space on any cell navigates to the corresponding
322	 * game page (`/footy/game/[id]`). No-game cells show the game day comment in
323	 * the tooltip when one is available.
324	 *
325	 * In the all-time view (`year === 0`) year panels are arranged side by side,
326	 * wrapping to the next row when the available width is exhausted. In a
327	 * single-year view (`year > 0`) one panel is rendered inline.
328	 *
329	 * @param props - See {@link Props}.
330	 */
331	export const PlayerHeatmap = ({ data, year }: Props) => {
332	    const wrapperRef = useRef<HTMLDivElement>(null);
333	    const tooltipRef = useRef<HTMLDivElement>(null);
334	    const svgRef = useRef<SVGSVGElement>(null);
335	    const router = useRouter();
336	
337	    const showTooltip = useCallback(
338	        (
339	            event: globalThis.MouseEvent,
340	            { date, label, comment }: TooltipContent,
341	        ) => {
342	            const el = tooltipRef.current;
343	            const wrapper = wrapperRef.current;
344	            /* c8 ignore next */
345	            if (!el || !wrapper) return;
346	            const wrapperRect = wrapper.getBoundingClientRect();
347	
348	            // Build content with text nodes — avoids innerHTML / XSS risk.
349	            el.textContent = '';
350	            const b = document.createElement('b');
351	            b.textContent = date;
352	            el.appendChild(b);
353	            el.appendChild(document.createElement('br'));
354	            el.appendChild(document.createTextNode(label));
355	            if (comment) {
356	                el.appendChild(document.createElement('br'));
357	                el.appendChild(document.createTextNode(comment));
358	            }
359	
360	            el.style.left = `${event.clientX - wrapperRect.left}px`;
361	            el.style.top = `${event.clientY - wrapperRect.top + 16}px`;
362	            el.style.opacity = '1';
363	        },
364	        [],
365	    );
366	
367	    const hideTooltip = useCallback(() => {
368	        /* c8 ignore next */
369	        if (tooltipRef.current) tooltipRef.current.style.opacity = '0';
370	    }, []);
371	
372	    // Single-year drawing
373	    useEffect(() => {
374	        if (year === 0 || !svgRef.current) return;
375	        const onCellClick = (gameId: number) =>
376	            router.push(`/footy/game/${gameId}`);
377	        const { cells, maxRow } = buildGrid(data);
378	        if (maxRow === 0) return;
379	        const { scale: xScale, iw } = makeXScale();
380	        const cellSize = xScale.bandwidth();
381	        const ih = maxRow * cellSize + Math.max(0, maxRow - 1) * GAP;
382	        const w = iw + M.left + M.right;
383	        const svg = select(svgRef.current);
384	        svg.selectAll('*').remove();
385	        svg.attr('width', w).attr('height', ih + M.top + M.bottom);
386	        const g = svg
387	            .append('g')
388	            .attr('transform', `translate(${M.left},${M.top})`);
389	        drawPanel(
390	            g,
391	            cells,
392	            maxRow,
393	            xScale,
394	            showTooltip,
395	            hideTooltip,
396	            onCellClick,
397	        );
398	    }, [data, hideTooltip, router, showTooltip, year]);
399	
400	    const yearGroups = useMemo(
401	        () => (year === 0 ? buildYearGroups(data) : null),
402	        [data, year],
403	    );
404	    const globalMaxRow = useMemo(
405	        () =>
406	            yearGroups ? Math.max(0, ...yearGroups.map((yg) => yg.maxRow)) : 0,
407	        [yearGroups],
408	    );
409	
410	    if (data.length === 0) {
411	        return (
412	            <Text
413	                c="dimmed"
414	                ta="center"
415	                py="xl"
416	            >
417	                No game data available.
418	            </Text>
419	        );
420	    }
421	
422	    if (year === 0) {
423	        return (
424	            <div
425	                ref={wrapperRef}
426	                className={styles.allTimeWrapper}
427	            >
428	                {yearGroups!.map(({ year: yr, cells }) => (
429	                    <YearPanel
430	                        key={yr}
431	                        label={yr}
432	                        cells={cells}
433	                        globalMaxRow={globalMaxRow}
434	                        showTooltip={showTooltip}
435	                        hideTooltip={hideTooltip}
436	                    />
437	                ))}
438	                <div
439	                    ref={tooltipRef}
440	                    className={styles.tooltip}
441	                />
442	            </div>
443	        );
444	    }
445	
446	    return (
447	        <div
448	            ref={wrapperRef}
449	            className={styles.wrapper}
450	        >
451	            <svg ref={svgRef} />
452	            <div
453	                ref={tooltipRef}
454	                className={styles.tooltip}
455	            />
456	        </div>
457	    );
458	};
