12	class ImmediateResizeObserver {
13	    private callback: ResizeObserverCallback;
14	    constructor(callback: ResizeObserverCallback) {
15	        this.callback = callback;
16	    }
17	    observe(_target: Element) {
18	        const entry = { contentRect: { width: 600 } };
19	        this.callback([entry as unknown as ResizeObserverEntry], this);
20	    }
21	    unobserve() {
22	        /* empty */
23	    }
24	    disconnect() {
