import { fireEvent, render, screen } from '@testing-library/react';
import { useRouter } from 'next/navigation';
import { vi } from 'vitest';

import { Wrapper } from '@/tests/components/lib/common';
import { createMockGameDay } from '@/tests/mocks/data/gameDay';
import { createMockOutcome } from '@/tests/mocks/data/outcome';
import { PlayerFormType } from '@/types';

import { buildGrid, buildYearGroups, PlayerHeatmap } from './PlayerHeatmap';

class ImmediateResizeObserver {
    private callback: ResizeObserverCallback;
    constructor(callback: ResizeObserverCallback) {
        this.callback = callback;
    }
    observe(_target: Element) {
        const entry = { contentRect: { width: 600 } };
        this.callback([entry as unknown as ResizeObserverEntry], this);
    }
    unobserve() {
        /* empty */
    }
    disconnect() {
        /* empty */
    }
}

/** One game per month in 2024, result cycling through win/draw/loss/null. */
const buildYearData = (): PlayerFormType[] =>
    Array.from({ length: 12 }, (_, i) => ({
        ...createMockOutcome({ gameDayId: i + 1 }),
        points: [3, 1, 0, null][i % 4] as 0 | 1 | 3 | null,
        gameDay: createMockGameDay({ id: i + 1, date: new Date(2024, i, 7) }),
    }));

/** Two games per year across 3 years, for all-time view. */
const buildAllTimeData = (): PlayerFormType[] =>
    [2022, 2023, 2024].flatMap((yr, yi) =>
        [0, 1].map((gi) => ({
            ...createMockOutcome({ gameDayId: yi * 2 + gi + 1 }),
            points: gi === 0 ? 3 : 0,
            gameDay: createMockGameDay({
                id: yi * 2 + gi + 1,
                date: new Date(yr, gi * 3, 7),
            }),
        })),
    );

/** One game + one no-game day (with no comment) in January 2024. */
const buildWithNoGameNoCommentData = (): PlayerFormType[] => [
    {
        ...createMockOutcome({ gameDayId: 1 }),
        points: 3,
        gameDay: createMockGameDay({
            id: 1,
            date: new Date(2024, 0, 7),
        }),
    },
    {
        id: -2,
        gameDayId: 2,
        playerId: 1,
        response: null,
        responseInterval: null,
        points: null,
        team: null,
        comment: null,
        pub: null,
        goalie: null,
        gameDay: createMockGameDay({
            id: 2,
            date: new Date(2024, 0, 14),
            status: 'NoGame',
            comment: null,
        }),
    },
];

/** One game + one no-game day in January 2024. */
const buildWithNoGameData = (): PlayerFormType[] => [
    {
        ...createMockOutcome({ gameDayId: 1 }),
        points: 3,
        gameDay: createMockGameDay({
            id: 1,
            date: new Date(2024, 0, 7),
        }),
    },
    {
        id: -2,
        gameDayId: 2,
        playerId: 1,
        response: null,
        responseInterval: null,
        points: null,
        team: null,
        comment: null,
        pub: null,
        goalie: null,
        gameDay: createMockGameDay({
            id: 2,
            date: new Date(2024, 0, 14),
            status: 'NoGame',
        }),
    },
];

/** One game with points=2 (not in colorMap or resultLabel) to exercise ?? fallbacks. */
const buildUnknownPointsData = (): PlayerFormType[] => [
    {
        ...createMockOutcome({ gameDayId: 1 }),
        points: 2 as unknown as 0 | 1 | 3,
        gameDay: createMockGameDay({ id: 1, date: new Date(2024, 0, 7) }),
    },
];

describe('buildGrid', () => {
    it('always produces 12 month columns', () => {
        const { cells } = buildGrid(buildYearData());
        const cols = [...new Set(cells.map((c) => c.col))];
        expect(cols).toHaveLength(12);
    });

    it('assigns row numbers starting at 1 within each column', () => {
        const { cells } = buildGrid(buildYearData());
        for (const col of ['Jan', 'Feb', 'Mar']) {
            const colCells = cells.filter((c) => c.col === col);
            expect(colCells[0].row).toBe(1);
        }
    });

    it('reports maxRow as the highest game count in any column', () => {
        const { maxRow } = buildGrid(buildYearData());
        expect(maxRow).toBe(1);
    });

    it('returns empty cells and maxRow 0 for empty input', () => {
        const { cells, maxRow } = buildGrid([]);
        expect(cells).toHaveLength(0);
        expect(maxRow).toBe(0);
    });

    it('marks cells as noGame when gameDay.status is NoGame', () => {
        const { cells } = buildGrid(buildWithNoGameData());
        const janCells = cells.filter((c) => c.col === 'Jan');
        expect(janCells).toHaveLength(2);
        expect(janCells.find((c) => c.noGame)).toBeDefined();
        expect(janCells.find((c) => !c.noGame)).toBeDefined();
    });

    it('skips entries without a gameDay', () => {
        const { cells, maxRow } = buildGrid([
            { ...createMockOutcome(), points: null, gameDay: undefined },
        ]);
        expect(cells).toHaveLength(0);
        expect(maxRow).toBe(0);
    });
});

describe('buildYearGroups', () => {
    it('returns one group per year, most recent first', () => {
        const groups = buildYearGroups(buildAllTimeData());
        expect(groups.map((g) => g.year)).toEqual(['2024', '2023', '2022']);
    });

    it('each group contains only the cells for that year', () => {
        const groups = buildYearGroups(buildAllTimeData());
        for (const group of groups) {
            expect(group.cells.length).toBeGreaterThan(0);
            expect(group.maxRow).toBeGreaterThan(0);
        }
    });

    it('returns an empty array for empty input', () => {
        expect(buildYearGroups([])).toHaveLength(0);
    });

    it('skips entries without a gameDay', () => {
        expect(
            buildYearGroups([
                { ...createMockOutcome(), points: null, gameDay: undefined },
            ]),
        ).toHaveLength(0);
    });
});

describe('PlayerHeatmap', () => {
    beforeEach(() => {
        vi.stubGlobal('ResizeObserver', ImmediateResizeObserver);
    });

    afterEach(() => {
        vi.unstubAllGlobals();
    });

    it('shows empty state when data is empty', () => {
        render(
            <Wrapper>
                <PlayerHeatmap
                    data={[]}
                    year={2024}
                />
            </Wrapper>,
        );
        expect(screen.getByText('No game data available.')).toBeInTheDocument();
    });

    it('renders a rect cell for each game in yearly view', () => {
        const data = buildYearData();
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={data}
                    year={2024}
                />
            </Wrapper>,
        );
        const cells = container.querySelectorAll('rect.cell');
        expect(cells.length).toBe(data.length);
    });

    it('renders a rect cell for each game in all-time view', () => {
        const data = buildAllTimeData();
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={data}
                    year={0}
                />
            </Wrapper>,
        );
        const cells = container.querySelectorAll('rect.cell');
        expect(cells.length).toBe(data.length);
    });

    it('renders month labels on the X axis for yearly view', () => {
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildYearData()}
                    year={2024}
                />
            </Wrapper>,
        );
        const labels = Array.from(container.querySelectorAll('svg text')).map(
            (el) => el.textContent,
        );
        expect(labels).toContain('J');
        expect(labels).toContain('D');
    });

    it('renders a year label for each year in the all-time view', () => {
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildAllTimeData()}
                    year={0}
                />
            </Wrapper>,
        );
        const labels = Array.from(container.querySelectorAll('svg text')).map(
            (el) => el.textContent,
        );
        expect(labels).toContain('2022');
        expect(labels).toContain('2023');
        expect(labels).toContain('2024');
    });

    it('renders month labels inside each year panel in the all-time view', () => {
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildAllTimeData()}
                    year={0}
                />
            </Wrapper>,
        );
        const labels = Array.from(container.querySelectorAll('svg text')).map(
            (el) => el.textContent,
        );
        expect(labels).toContain('F');
        expect(labels).toContain('D');
    });

    it('shows tooltip with date and result on mousemove', () => {
        const data = buildYearData();
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={data}
                    year={2024}
                />
            </Wrapper>,
        );
        const cell = container.querySelector('rect.cell')!;
        const tooltipDiv = container.querySelector('svg')!
            .nextElementSibling as HTMLElement;

        fireEvent.mouseMove(cell);
        expect(tooltipDiv.style.opacity).toBe('1');
        expect(tooltipDiv.innerHTML).toContain('2024');
    });

    it('hides tooltip on mouseleave', () => {
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildYearData()}
                    year={2024}
                />
            </Wrapper>,
        );
        const cell = container.querySelector('rect.cell')!;
        const tooltipDiv = container.querySelector('svg')!
            .nextElementSibling as HTMLElement;

        fireEvent.mouseMove(cell);
        expect(tooltipDiv.style.opacity).toBe('1');

        fireEvent.mouseLeave(cell);
        expect(tooltipDiv.style.opacity).toBe('0');
    });

    it('shows "No game" and the game day comment in tooltip for a no-game day cell', () => {
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildWithNoGameData()}
                    year={2024}
                />
            </Wrapper>,
        );
        const cells = container.querySelectorAll('rect.cell');
        // Second cell in January is the no-game day (14 Jan)
        const tooltipDiv = container.querySelector('svg')!
            .nextElementSibling as HTMLElement;
        fireEvent.mouseMove(cells[1]);
        expect(tooltipDiv.innerHTML).toContain('No game');
        // createMockGameDay defaults comment to 'I heart footy'
        expect(tooltipDiv.innerHTML).toContain('I heart footy');
    });

    it('navigates to the game day page when a no-game cell is clicked', () => {
        const push = useRouter().push as ReturnType<typeof vi.fn>;
        push.mockClear();

        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildWithNoGameData()}
                    year={2024}
                />
            </Wrapper>,
        );
        const cells = container.querySelectorAll('rect.cell');
        // Second cell is the no-game day with gameDayId = 2
        fireEvent.click(cells[1]);
        expect(push).toHaveBeenCalledWith('/footy/game/2');
    });

    it('navigates to the game page when Enter is pressed on a cell', () => {
        const push = useRouter().push as ReturnType<typeof vi.fn>;
        push.mockClear();

        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildYearData()}
                    year={2024}
                />
            </Wrapper>,
        );
        const cell = container.querySelector('rect.cell')!;
        fireEvent.keyDown(cell, { key: 'Enter' });
        expect(push).toHaveBeenCalledWith('/footy/game/1');
    });

    it('navigates to the game page when Space is pressed on a cell', () => {
        const push = useRouter().push as ReturnType<typeof vi.fn>;
        push.mockClear();

        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildYearData()}
                    year={2024}
                />
            </Wrapper>,
        );
        const cell = container.querySelector('rect.cell')!;
        fireEvent.keyDown(cell, { key: ' ' });
        expect(push).toHaveBeenCalledWith('/footy/game/1');
    });

    it('does not navigate when an unrelated key is pressed on a cell', () => {
        const push = useRouter().push as ReturnType<typeof vi.fn>;
        push.mockClear();

        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildYearData()}
                    year={2024}
                />
            </Wrapper>,
        );
        const cell = container.querySelector('rect.cell')!;
        fireEvent.keyDown(cell, { key: 'Tab' });
        expect(push).not.toHaveBeenCalled();
    });

    it('shows plain "No game" aria-label for a no-game day with no comment', () => {
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildWithNoGameNoCommentData()}
                    year={2024}
                />
            </Wrapper>,
        );
        const cells = container.querySelectorAll('rect.cell');
        const label = cells[1].getAttribute('aria-label') ?? '';
        expect(label).toContain('No game');
        expect(label).not.toContain('—');
    });

    it('renders no cells when all entries lack a gameDay', () => {
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={[
                        {
                            ...createMockOutcome(),
                            points: null,
                            gameDay: undefined,
                        },
                    ]}
                    year={2024}
                />
            </Wrapper>,
        );
        expect(container.querySelectorAll('rect.cell')).toHaveLength(0);
    });

    it('renders cell and shows tooltip with fallback for unknown points value', () => {
        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildUnknownPointsData()}
                    year={2024}
                />
            </Wrapper>,
        );
        const cell = container.querySelector('rect.cell')!;
        expect(cell).toBeDefined();
        const tooltipDiv = container.querySelector('svg')!
            .nextElementSibling as HTMLElement;
        fireEvent.mouseMove(cell);
        expect(tooltipDiv.style.opacity).toBe('1');
    });

    it('navigates to game page on cell click in all-time view', () => {
        const push = useRouter().push as ReturnType<typeof vi.fn>;
        push.mockClear();

        const { container } = render(
            <Wrapper>
                <PlayerHeatmap
                    data={buildAllTimeData()}
                    year={0}
                />
            </Wrapper>,
        );
