/**
 * Builds an Outcome where-clause matching outcomes that derive to the given
 * points value, or (when `points` is undefined) any outcome with a decided
 * result.
 */
const outcomeWhereForPoints = (
    points: PointsValue | undefined,
    gameDayWhere: Prisma.GameDayWhereInput = {},
): Prisma.OutcomeWhereInput => {
    if (points === undefined) {
        return {
            team: { not: null },
            gameDay: {
                status: { in: ['AWin', 'BWin', 'Draw'] },
                ...gameDayWhere,
            },
        };
    }
    if (points === 1) {
        return { gameDay: { status: 'Draw', ...gameDayWhere } };
    }

    const winningStatus: GameDayStatus = points === 3 ? 'AWin' : 'BWin';
    const losingStatus: GameDayStatus = points === 3 ? 'BWin' : 'AWin';

    return {
        OR: [
            {
                team: 'A',
                gameDay: { status: winningStatus, ...gameDayWhere },
            },
            {
                team: 'B',
                gameDay: { status: losingStatus, ...gameDayWhere },
            },
        ],
    };
};

