 * @param year - An optional year to limit the search range.
 * @param points - An optional points filter: if provided, only outcomes
 * with this points value will be returned. If not, the most recent outcome
 * with any non-null points value will be returned.
 * @returns A promise that resolves to the player's latest outcome including
 * its game day, or `null` if none is found.
 * @throws Will propagate any errors encountered during the retrieval
 * process.
 */
async getLastResult(
    playerId: number,
    year?: number,
    points?: PointsValue,
): Promise<PlayerFormType | null> {
    const id = z.coerce.number().int().min(1).parse(playerId);
    const validatedPoints = PointsSchema.optional().parse(points);
    const gameDayWhere: Prisma.GameDayWhereInput = {
        date: {
            gte: year ? new Date(Date.UTC(year, 0, 1)) : undefined,
            lt: year ? new Date(Date.UTC(year + 1, 0, 1)) : undefined,
        },
    };

    let pointsWhere: Prisma.OutcomeWhereInput;
    if (validatedPoints === undefined) {
        pointsWhere = decidedGameWhere(gameDayWhere);
    } else if (validatedPoints === 1) {
        pointsWhere = { gameDay: { status: 'Draw', ...gameDayWhere } };
    } else {
        const winningStatus: GameDayStatus =
            validatedPoints === 3 ? 'AWin' : 'BWin';
        const losingStatus: GameDayStatus =
            validatedPoints === 3 ? 'BWin' : 'AWin';
        pointsWhere = {
            OR: [
                {
                    team: 'A',
                    gameDay: { status: winningStatus, ...gameDayWhere },
                },
                {
                    team: 'B',
                    gameDay: { status: losingStatus, ...gameDayWhere },
                },
            ],
        };
    }

    const outcome = await prisma.outcome.findFirst({
        where: {
            playerId: id,
            ...pointsWhere,
        },
        orderBy: {
            gameDayId: 'desc',
        },
        include: {
            gameDay: true,
        },
        take: 1,
    });

    return outcome
        ? {
              ...outcome,
              points: getPlayerPoints(outcome.gameDay.status, outcome.team),
          }
        : null;
}

