43	     * player's trimmed name, falling back to a generic name if the name is
44	     * empty or null. A `null` value for `anonymous` is treated as not anonymous
45	     * (equivalent to `false`).
46	     *
47	     * @param player - The player object containing id, name, and anonymous flag
48	     * @param player.id - The unique identifier for the player
49	     * @param player.name - The player's name, can be null
50	     * @param player.anonymous - Whether the player is anonymous; `true` marks
51	     * the player as anonymous, while `false` or a `null` value are treated as
52	     * not anonymous
53	     * @returns The display name for the player
54	     */
55	    private getDisplayName(player: {
56	        id: number;
57	        name: string | null;
58	        anonymous: boolean | null;
59	    }) {
60	        if (player.anonymous) {
61	            return `Player ${player.id}`;
