                    </Grid.Col>
                    <Grid.Col span={playerCardsGridColSpan}>
                        <PlayerInfo
                            player={player}
                            year={year}
                            introducedBy={introducedBy}
                            lastPlayed={lastPlayed}
                            lastWon={lastWon}
                            isAuthenticated={isAuthenticated}
                            isAdmin={isAdmin}
                            playerData={playerData}
                            onSendEmail={onSendEmail}
                        />
                    </Grid.Col>
                    <Grid.Col span={playerCardsGridColSpan}>
                        <PlayerResults
                            player={player}
                            year={year}
                            record={record}
                        />
                    </Grid.Col>
                    <Grid.Col span={playerCardsGridColSpan}>
                        <PlayerPositions
                            player={player}
                            year={year}
                            record={record}
                        />
                    </Grid.Col>
                </Grid>
                <Paper
                    p="sm"
                    w="auto"
                    style={{ flex: '1' }}
                >
                    <PlayerHeatmap
                        data={history}
                        year={year}
                    />
                </Paper>
            </Stack>
        </Container>
    );
};

