import { readFileSync } from 'fs';

const gameDays = JSON.parse(readFileSync('db-snapshot/GameDay.json', 'utf8'));
const outcomes = JSON.parse(readFileSync('db-snapshot/Outcome.json', 'utf8'));

console.log(`Loaded ${gameDays.length} game days, ${outcomes.length} outcomes`);

// Group outcomes by gameDayId + team
const byGameDayTeam = new Map(); // key: `${gameDayId}:${team}` -> Set of distinct points values (non-null)

for (const o of outcomes) {
    if (o.team === null || o.team === undefined) continue;
    if (o.points === null || o.points === undefined) continue;
    const key = `${o.gameDayId}:${o.team}`;
    if (!byGameDayTeam.has(key)) byGameDayTeam.set(key, new Set());
    byGameDayTeam.get(key).add(o.points);
}

// Find any gameDayId:team combo with more than 1 distinct points value
const inconsistent = [];
for (const [key, pointsSet] of byGameDayTeam.entries()) {
    if (pointsSet.size > 1) {
        const [gameDayId, team] = key.split(':');
        inconsistent.push({ gameDayId: Number(gameDayId), team, points: [...pointsSet] });
    }
}

console.log(`\nTotal distinct (gameDayId, team) pairs with points: ${byGameDayTeam.size}`);
console.log(`Inconsistent (non-unanimous) pairs found: ${inconsistent.length}`);

if (inconsistent.length > 0) {
    console.log('\nDetails:');
    for (const entry of inconsistent) {
        const gd = gameDays.find((g) => g.id === entry.gameDayId);
        console.log(entry, 'gameDay:', gd ? { id: gd.id, date: gd.date, game: gd.game } : 'NOT FOUND');
    }
} else {
    console.log('\nNo inconsistencies found: every (gameDayId, team) pair with recorded points has exactly one distinct points value.');
}

// Also cross-check: for every game day where game=true, do the aPoints/bPoints (via MAX, matching migration SQL)
// actually correspond to a valid pairing (3&0, 0&3, or 1&1)? Report any mismatches / unexpected pairings.
const gameDaysById = new Map(gameDays.map((g) => [g.id, g]));
const pointsByGameDay = new Map(); // gameDayId -> {A: Set, B: Set}
for (const o of outcomes) {
    if (o.team !== 'A' && o.team !== 'B') continue;
    if (o.points === null || o.points === undefined) continue;
    if (!pointsByGameDay.has(o.gameDayId)) pointsByGameDay.set(o.gameDayId, { A: new Set(), B: new Set() });
    pointsByGameDay.get(o.gameDayId)[o.team].add(o.points);
}

let unexpectedPairings = 0;
let totalWithBothTeams = 0;
for (const [gameDayId, { A, B }] of pointsByGameDay.entries()) {
    if (A.size === 0 || B.size === 0) continue;
    totalWithBothTeams++;
    const aMax = Math.max(...A);
    const bMax = Math.max(...B);
    const validPairs = [[3, 0], [0, 3], [1, 1]];
    const isValid = validPairs.some(([a, b]) => a === aMax && b === bMax);
    if (!isValid || A.size > 1 || B.size > 1) {
        unexpectedPairings++;
        const gd = gameDaysById.get(gameDayId);
        console.log('Unexpected pairing:', { gameDayId, aPointsSet: [...A], bPointsSet: [...B], gameDay: gd ? { date: gd.date, game: gd.game } : 'N/A' });
    }
}

console.log(`\nGame days with points on both teams: ${totalWithBothTeams}`);
console.log(`Unexpected/non-unanimous pairings: ${unexpectedPairings}`);

