import { TableName, TableNameSchema } from 'prisma/zod/schemas';
import { PlayerRecordType } from 'prisma/zod/schemas/models/PlayerRecord.schema';

import { config } from '@/lib/config';

export function getYearName(year: number): string {
    return year == 0 ? 'All-time' : year.toString();
}

/**
 * The PlayerRecord rank field(s) a TableName is ranked by: [primary,
 * unqualified variant]. `Pick` requires every member to be a real
 * PlayerRecordType key, so a future rename of any of these fields fails this
 * type rather than silently drifting.
 */
type RankField = keyof Pick<
    PlayerRecordType,
    | 'rankPoints'
    | 'rankAverages'
    | 'rankAveragesUnqualified'
    | 'rankStalwart'
    | 'rankSpeedy'
    | 'rankSpeedyUnqualified'
    | 'rankPub'
>;

export const rankMap: Record<TableName, [RankField, RankField | undefined]> = {
    points: ['rankPoints', undefined],
    averages: ['rankAverages', 'rankAveragesUnqualified'],
    stalwart: ['rankStalwart', undefined],
    speedy: ['rankSpeedy', 'rankSpeedyUnqualified'],
    pub: ['rankPub', undefined],
};

/**
 * The PlayerRecord score field a TableName ranks by. `Pick` requires every
 * member to be a real PlayerRecordType key, so a future rename of any of
 * these fields fails this type rather than silently drifting.
 */
type ScoreField = keyof Pick<
    PlayerRecordType,
    | 'scorePoints'
    | 'scoreAverages'
    | 'scoreStalwart'
    | 'scoreSpeedy'
    | 'scorePub'
>;

/** Maps a TableName to the PlayerRecord field it ranks by. */
export const scoreFieldMap: Record<TableName, ScoreField> = {
    points: 'scorePoints',
    averages: 'scoreAverages',
    stalwart: 'scoreStalwart',
    speedy: 'scoreSpeedy',
    pub: 'scorePub',
};

export function ShortTableTitle(table: TableName): string {
    return table.charAt(0).toUpperCase() + table.slice(1);
}

export function TableTitle(table: TableName): string {
    switch (table) {
        case TableNameSchema.enum.speedy:
            return 'Captain Speedy';
        case TableNameSchema.enum.stalwart:
            return 'Stalwart Standings';
        default:
            return table.charAt(0).toUpperCase() + table.slice(1) + ' Table';
    }
}

export function QualifiedTableName(table: TableName, year: number): string {
    return `${getYearName(year)} ${TableTitle(table)}`;
}

export function UnqualifiedTableName(table: TableName): string | undefined {
    switch (table) {
        case TableNameSchema.enum.averages:
            return `Played Fewer than ${config.minGamesForAveragesTable} Games`;
        case TableNameSchema.enum.speedy:
            return `Responded Fewer than ${config.minRepliesForSpeedyTable} Times`;
        default:
            return undefined;
    }
}

'use client';

import type { TitleOrder } from '@mantine/core';
import { Anchor, Divider, Paper, Table, Title } from '@mantine/core';
import { TableNameSchema } from 'prisma/zod/schemas';
import type { PlayerRecordType } from 'prisma/zod/schemas/models/PlayerRecord.schema';

import { getYearName, rankMap } from '@/lib/tables';
import { PlayerDisplayType } from '@/services/Player';

export interface Props {
    player: PlayerDisplayType;
    year: number;
    record: PlayerRecordType | null;
    titleOrder?: TitleOrder;
}

export const PlayerPositions = ({
    player,
    year,
    record,
    titleOrder = 3,
}: Props) => {
    return (
        <Paper
            p="sm"
            miw="14rem"
            h="100%"
        >
            <Title
                order={titleOrder}
                mb="xs"
                w="100%"
                ta="center"
            >
                Positions
            </Title>
            <Divider mb="xs" />
            <Table
                summary={`${player.name}'s ${getYearName(year)} table positions`}
                layout="fixed"
            >
                <Table.Tbody>
                    {TableNameSchema.options.map((table) => {
                        const position = record
                            ? (record[rankMap[table][0]] ?? null)
                            : null;
                        const href = `/footy/table/${table}?year=${year}`;

                        return (
                            <Table.Tr key={table}>
                                <Table.Th>
                                    <Anchor href={href}>
                                        {table.charAt(0).toUpperCase() +
                                            table.slice(1)}
                                    </Anchor>
                                </Table.Th>
                                <Table.Td w="3rem">
                                    {position !== null ? (
                                        <Anchor href={href}>{position}</Anchor>
                                    ) : (
                                        '-'
                                    )}
                                </Table.Td>
                            </Table.Tr>
                        );
                    })}
                </Table.Tbody>
            </Table>
        </Paper>
    );
};

import { TableName, TableNameSchema } from 'prisma/zod/schemas';
import { PlayerRecordType } from 'prisma/zod/schemas/models/PlayerRecord.schema';

import { rankMap } from '@/lib/tables';
import { createMockGameDay } from '@/tests/mocks/data/gameDay';
import type { PlayerLastResultType } from '@/types/PlayerLastResultType';

export const minimalPlayerRecord = {
    id: 1,
    year: 2021,
    gamesPlayed: 10,
    gameDayId: 15,
    playerId: 12,
} satisfies PlayerRecordType;

export const defaultPlayerRecord = {
    ...minimalPlayerRecord,
    responses: 10,
    played: 10,
    won: 5,
    drawn: 3,
    lost: 2,
    scorePoints: 18,
    scoreAverages: 1.8,
    scoreStalwart: 5,
    scorePub: 1,
    scoreSpeedy: 4,
    rankPoints: 1,
    rankAverages: 2,
    rankAveragesUnqualified: 2,
    rankStalwart: 3,
    rankSpeedy: 4,
    rankSpeedyUnqualified: 4,
    rankPub: 5,
} satisfies PlayerRecordType;

export const createMockPlayerRecord = (
    overrides: Partial<PlayerRecordType> = {},
): PlayerRecordType => ({
    ...defaultPlayerRecord,
    ...overrides,
});

export const createMockPlayerLastResult = (
    overrides: Partial<PlayerLastResultType> = {},
): PlayerLastResultType => ({
    ...createMockPlayerRecord(),
    gameDay: createMockGameDay(),
    ...overrides,
});

/**
 * Generates a list of varied mock player records for testing.
 * Creates records with:
 * - Multiple players (20 different players)
 * - Multiple years (2020-2024)
 * - Varied game days
 * - Varied ranking positions (cycles through ranks 1-5)
 * - Varied statistics (points, averages, stalwart, speedy, pub)
 *
 * Note: The first record matches defaultPlayerRecord to maintain backward compatibility.
 */
export const defaultPlayerRecordList: PlayerRecordType[] = [
    // First record is the default player record for backward compatibility
    defaultPlayerRecord,
    // Generate 99 more varied records
    ...Array.from({ length: 99 }, (_, i) => {
        const index = i + 1; // Start from 1 since 0 is the default record
        const playerId = (index % 20) + 1;
        const year = 2020 + Math.floor(index / 20);
        const gameDayId = 10 + Math.floor(index / 10) + 1;

        // Create varied rankings - cycles through ranks 1-5
        const rankPosition = (index % 5) + 1;

        // Vary stats based on ranking
        const basePlayed = 10 + (index % 5);
        const baseWon = Math.max(0, basePlayed - rankPosition);
        const baseDrawn = Math.min(
            3,
            Math.min(index % 4, basePlayed - baseWon),
        );
        const baseLost = Math.max(0, basePlayed - baseWon - baseDrawn);

        // Points table stats (3 points for win, 1 for draw)
        const points = baseWon * 3 + baseDrawn;

        return createMockPlayerRecord({
            id: index + 1,
            playerId,
            year,
            gameDayId,

            // Varied game statistics
            responses: basePlayed,
            played: basePlayed,
            won: baseWon,
            drawn: baseDrawn,
            lost: baseLost,

            // Points table stats
            scorePoints: points,
            scoreAverages: parseFloat((points / basePlayed).toFixed(2)),

            // Other table stats
            scoreStalwart: basePlayed - (rankPosition - 1),
            scoreSpeedy: Math.max(1, 6 - rankPosition),
            scorePub: Math.max(1, 6 - rankPosition),

            // Rankings - vary across different tables
            rankPoints: rankPosition,
            rankAverages: ((rankPosition + 1) % 5) + 1,
            rankAveragesUnqualified: ((rankPosition + 1) % 5) + 1,
            rankStalwart: ((rankPosition + 2) % 5) + 1,
            rankSpeedy: ((rankPosition + 3) % 5) + 1,
            rankSpeedyUnqualified: ((rankPosition + 3) % 5) + 1,
            rankPub: ((rankPosition + 4) % 5) + 1,
        });
    }),
];

/**
 * Generates default trophies map with winners across all ranking tables.
 * Each table will have records where the player ranked 1st.
 */
export const defaultTrophiesList = new Map<TableName, PlayerRecordType[]>();
TableNameSchema.options.forEach((table) => {
    const rank = rankMap[table][0];
    defaultTrophiesList.set(
        table,
        defaultPlayerRecordList.filter((record) => record[rank] === 1),
    );
});

