/**
 * Looks up a score's precomputed rank.
 * @param ranks - A score-to-rank map built by `rankByScore` from the same
 * array the score was drawn from.
 * @param score - The score to look up.
 * @returns The score's 1-based rank.
 * @throws {InternalError} If the score is absent from the map, which means
 * it was filtered into the ranked array under different criteria than were
 * used here to look it up.
 */
function getRank(ranks: Map<number, number>, score: number): number {
    const rank = ranks.get(score);
    if (rank === undefined) {
        throw new InternalError(
            `Score ${score} is missing from its precomputed rank map.`,
            { details: { score } },
        );
    }
    return rank;
}

