593	/**
594	 * Builds a score-to-rank lookup from an array of scores already sorted into
595	 * rank order (best first). Tied scores share the rank of their first
596	 * occurrence, matching `Array.prototype.indexOf` semantics but computed once
597	 * in O(n) rather than on every O(n) lookup.
598	 * @param sortedScores - Scores sorted into rank order (best first).
599	 * @returns A map from score to its 1-based rank.
600	 */
601	function rankByScore(sortedScores: number[]): Map<number, number> {
602	    const ranks = new Map<number, number>();
603	    sortedScores.forEach((score, index) => {
604	        if (!ranks.has(score)) {
605	            ranks.set(score, index + 1);
606	        }
607	    });
608	    return ranks;
609	}
610	
611	/**
