import prisma from 'prisma/prisma';
import {
    OutcomeWhereUniqueInputObjectSchema,
    PlayerResponseSchema,
    TeamName,
    TeamNameSchema,
} from 'prisma/zod/schemas';
import { OutcomeType } from 'prisma/zod/schemas/models/Outcome.schema';
import z from 'zod';

import { InternalError } from '@/lib/errors';
import { getPlayerPoints, isGame } from '@/lib/gameResult';
import { isPrismaNotFoundError } from '@/lib/prismaErrors';
import gameDayService from '@/services/GameDay';
import {
    PlayerFormType,
    TeamPlayerSchema,
    type TeamPlayerType,
    Turnout,
    TurnoutByYearType,
    WDLType,
} from '@/types';
import { OutcomePlayerType } from '@/types/OutcomePlayerType';
import {
    OutcomeCreateOneStrictSchema,
    OutcomeUpsertOneStrictSchema,
    type OutcomeWriteInput,
    OutcomeWriteInputSchema,
} from '@/types/OutcomeStrictSchema';
import type { PointsValue } from '@/types/Points';

/** Linear merge of two PlayerFormType arrays already sorted by date then id. */
function mergeByDate(
    a: PlayerFormType[],
    b: PlayerFormType[],
): PlayerFormType[] {
    const result: PlayerFormType[] = [];
    let i = 0;
    let j = 0;
    while (i < a.length && j < b.length) {
        const dateDiff =
            a[i].gameDay!.date.getTime() - b[j].gameDay!.date.getTime();
        if (
            dateDiff < 0 ||
            (dateDiff === 0 && a[i].gameDay!.id <= b[j].gameDay!.id)
        ) {
            result.push(a[i++]);
        } else {
            result.push(b[j++]);
        }
    }
    while (i < a.length) result.push(a[i++]);
    while (j < b.length) result.push(b[j++]);
    return result;
}

class OutcomeService {
    /**
     * Retrieves an Outcome for the given Player ID for the given GameDay ID.
     * @param gameDayId - The ID of the GameDay.
     * @param playerId - The ID of the Player.
     * @returns A promise that resolves to the Outcome if found, otherwise null.
     * @throws An error if there is a failure.
     */
    async get(
        gameDayId: number,
        playerId: number,
    ): Promise<OutcomeType | null> {
        const where = OutcomeWhereUniqueInputObjectSchema.parse({
            gameDayId_playerId: {
                gameDayId: gameDayId,
                playerId: playerId,
            },
        });

        return prisma.outcome.findUnique({ where });
    }

    /**
     * Retrieves all outcomes.
     * @returns A promise that resolves to an array of outcomes.
     */
    async getAll(): Promise<OutcomeType[]> {
        return prisma.outcome.findMany({});
    }

    /**
     * Retrieves the last played outcome.
     * @returns A Promise that resolves to the last played Outcome, or null if no outcome is found.
     */
    async getLastPlayed(): Promise<OutcomeType | null> {
        return prisma.outcome.findFirst({
            where: {
                team: { not: null },
                gameDay: { status: { in: ['AWin', 'BWin', 'Draw'] } },
            },
            orderBy: {
                gameDayId: 'desc',
            },
        });
    }

    /**
     * Retrieves all the outcomes for gameDays in a given year, or all years if
     * `year` is zero.
     * @param year - The year to include, or zero for all year.
     * @param untilGameDay - The gameDay ID to stop at (inclusive), or undefined
     * to include all.
     * @returns A promise that resolves to an array of Outcomes sorted by
     * gameDay, most recent first.
     * @throws An error if there is a failure.
     */
    async getAllForYear(
        year: number,
        untilGameDay?: number,
    ): Promise<OutcomeType[]> {
        return prisma.outcome.findMany({
            where: {
                gameDay: {
                    date:
                        year !== 0
                            ? {
                                  gte: new Date(Date.UTC(year, 0, 1)),
                                  lt: new Date(Date.UTC(year + 1, 0, 1)),
                              }
                            : {},
                    id: untilGameDay
                        ? {
                              lte: untilGameDay,
                          }
                        : {},
                },
            },
            orderBy: {
                gameDayId: 'desc',
            },
        });
    }

    /**
     * Retrieves the response counts for a specific game day or all game days.
     *
     * @param gameDayId - Optional. The ID of the game day to retrieve response counts for.
     * @returns An array of game days with their corresponding response counts.
     * @throws If there is an error fetching the outcomes.
     */
    async getResponseCounts(gameDayId?: number) {
        return prisma.outcome.groupBy({
            orderBy: {
                gameDayId: 'asc',
            },
            where: {
                ...(gameDayId ? { gameDayId: gameDayId } : {}),
            },
            by: ['response', 'gameDayId'],
            _count: {
                response: true,
                team: true,
            },
        });
    }

    /**
     * Retrieves the turnout for a specific game day or all game days.
     *
     * @param gameDayId - Optional. The ID of the game day to retrieve turnout for.
     * @returns An array of game days with their corresponding response counts.
     * @throws If there is an error fetching the outcomes.
     */
    async getTurnout(gameDayId?: number): Promise<Turnout[]> {
        const responseCounts = await this.getResponseCounts(gameDayId);

        let gameDays = [];
        if (gameDayId === undefined) {
            gameDays = await gameDayService.getAll();
        } else {
            gameDays.push(await gameDayService.get(gameDayId));
        }

        const result = gameDays.map((gameDay) => {
            const initialResponseCounts = new Map<string, number>([
                ['yes', 0],
                ['no', 0],
                ['dunno', 0],
                ['excused', 0],
                ['flaked', 0],
                ['injured', 0],
            ]);
            const gameDayResponseCounts = PlayerResponseSchema.options.reduce(
                (map, response) => {
                    const count =
                        responseCounts
                            .filter(
                                (res) =>
                                    res.gameDayId === gameDay?.id &&
                                    res.response === `${response}`,
                            )
                            .map((res) => res._count.response)[0] || 0;
                    map.set(`${response.toLowerCase()}`, count);
                    return map;
                },
                initialResponseCounts,
            );

            if (gameDay) {
                return {
                    ...gameDay,
                    game: isGame(gameDay.status),
                    yes: gameDayResponseCounts.get('yes'),
                    no: gameDayResponseCounts.get('no'),
                    dunno: gameDayResponseCounts.get('dunno'),
                    excused: gameDayResponseCounts.get('excused'),
                    flaked: gameDayResponseCounts.get('flaked'),
                    injured: gameDayResponseCounts.get('injured'),
                    responses: responseCounts
                        .filter(
                            (rc) =>
                                rc.gameDayId === gameDay.id &&
                                rc.response !== null,
                        )
                        .reduce((acc, rc) => acc + rc._count.response, 0),
                    players:
                        responseCounts
                            .filter(
                                (rc) =>
                                    rc.gameDayId === gameDay.id &&
                                    rc.response ===
                                        PlayerResponseSchema.enum.Yes,
                            )
                            .map((rc) => rc._count.team)[0] || 0,
                    cancelled:
                        gameDay.mailSent !== null &&
                        gameDay.status === 'NoGame',
                };
            }
        });

        return result as Turnout[];
    }

    /**
     * Retrieves the turnout data by year.
     * @returns A promise that resolves to an array of `TurnoutByYear` objects.
     * @throws If there is an error fetching the outcomes.
     */
    async getTurnoutByYear(): Promise<TurnoutByYearType[]> {
        const turnout = await this.getTurnout();
        const gameYears = await gameDayService.getAllYears({});

        return gameYears.map((gameYear) => {
            const yearTurnout = turnout.filter((t) => gameYear === t.year);
            const result: TurnoutByYearType = {
                year: gameYear,
                gameDays: yearTurnout.length,
                gamesScheduled: yearTurnout.filter((t) => t.game || t.mailSent)
                    .length,
                gamesInitiated: yearTurnout.filter((t) => t.mailSent).length,
                gamesPlayed: yearTurnout.filter((t) => t.game && t.mailSent)
                    .length,
                gamesCancelled: yearTurnout.filter((t) => t.cancelled).length,
                responses: yearTurnout.reduce((acc, t) => acc + t.responses, 0),
                yesses: yearTurnout.reduce((acc, t) => acc + t.yes, 0),
                players: yearTurnout.reduce((acc, t) => acc + t.players, 0),
                responsesPerGameInitiated: 0,
                yessesPerGameInitiated: 0,
                playersPerGamePlayed: 0,
            };

            if (result.gamesInitiated > 0) {
                result.responsesPerGameInitiated = parseFloat(
                    (result.responses / result.gamesInitiated).toFixed(1),
                );
                result.yessesPerGameInitiated = parseFloat(
                    (result.yesses / result.gamesInitiated).toFixed(1),
                );
            }
            if (result.gamesPlayed > 0) {
                result.playersPerGamePlayed = parseFloat(
                    (result.players / result.gamesPlayed).toFixed(1),
                );
            }

            return result;
        });
    }

    /**
     * Retrieves outcomes by game day ID and, optionally, team.
     * @param gameDayId - The ID of the game day.
     * @param team - Optional team ('A' or 'B').
     * @returns A promise that resolves to an array of Outcome objects.
     * @throws If there is an error fetching the outcomes.
     */
    async getByGameDay(
        gameDayId: number,
        team?: 'A' | 'B',
    ): Promise<OutcomePlayerType[]> {
        const outcomes = await prisma.outcome.findMany({
            where: {
                gameDayId,
                team,
            },
            include: {
                player: true,
                gameDay: { select: { status: true } },
            },
        });

        return outcomes.map(({ gameDay, ...outcome }) => ({
            ...outcome,
            points: getPlayerPoints(gameDay.status, outcome.team),
        }));
    }

    /**
     * Retrieves admin response rows for a game day, including active players
     * who do not yet have an Outcome for that game day.
     * @param gameDayId - The ID of the game day.
     * @returns A promise that resolves to one row per active player.
     * @throws If there is an error fetching the data.
     */
    async getAdminByGameDay(gameDayId: number): Promise<OutcomePlayerType[]> {
        const validatedGameDayId = z.number().int().min(1).parse(gameDayId);

        const [gameDay, activePlayers] = await Promise.all([
            gameDayService.get(validatedGameDayId),
            prisma.player.findMany({
                where: {
                    finished: null,
                },
                orderBy: [{ name: 'asc' }, { id: 'asc' }],
                include: {
                    outcomes: {
                        where: {
                            gameDayId: validatedGameDayId,
                        },
                        take: 1,
                    },
                },
            }),
        ]);
        const status = gameDay?.status ?? 'NoGame';

        return activePlayers.map(({ outcomes, ...player }) => {
            const outcome = outcomes[0];
            if (outcome) {
                return OutcomePlayerType.parse({
                    ...outcome,
                    points: getPlayerPoints(status, outcome.team),
                    player,
                });
            }

            return OutcomePlayerType.parse({
                id: -player.id,
                gameDayId: validatedGameDayId,
                playerId: player.id,
                response: null,
                responseInterval: null,
                points: null,
                team: null,
                comment: null,
                pub: null,
                goalie: null,
                player,
            });
        });
    }

    /**
     * Retrieves all players on a given team for a specific game day, including
     * their outcome for that day and their recent form.
     * @param gameDayId - The game day identifier.
     * @param team - Team to fetch ('A' or 'B').
     * @param formHistory - Number of previous games to include in each
     * player's form graph (default 5, minimum 0).
     *
     * Form behavior:
     * - Uses only prior outcomes with a team assigned on a decided game day.
     * - Prior outcomes are returned oldest → newest.
     * - If fewer than formHistory outcomes exist, form is left-padded with
     *   unplayed sentinel entries (gameDayId: 0, points: null) so the result
     *   is always formHistory entries long.
     *
     * Sorting behavior:
     * - Players are ordered with goalies first.
     * - Within each group, players are ordered alphabetically by name.
     * @returns A promise resolving to the enriched player records.
     * @throws If there is an error fetching the data.
     */
    async getTeamPlayersByGameDay(
        gameDayId: number,
        team: TeamName,
        formHistory = 5,
    ): Promise<TeamPlayerType[]> {
        const validatedGameDayId = z.number().int().min(1).parse(gameDayId);
        const validatedTeam = TeamNameSchema.parse(team);
        const validatedHistory = z.number().int().min(0).parse(formHistory);

        const outcomes = await prisma.outcome.findMany({
            where: {
                gameDayId: validatedGameDayId,
                team: validatedTeam,
            },
            include: {
                gameDay: true,
                player: {
                    include: {
                        outcomes: {
                            where: {
                                gameDayId: { lt: validatedGameDayId },
                                team: { not: null },
                                gameDay: {
                                    status: { in: ['AWin', 'BWin', 'Draw'] },
                                },
                            },
                            orderBy: { gameDayId: 'desc' },
                            take: validatedHistory,
                            include: { gameDay: true },
                        },
                    },
                },
            },
            orderBy: [{ goalie: 'desc' }, { player: { name: 'asc' } }],
        });

        return outcomes.map(({ player, gameDay, ...outcome }) => {
            if (!player) {
                throw new InternalError(
                    `Outcome ${outcome.id} is missing its player relation.`,
                    {
                        details: {
                            outcomeId: outcome.id,
                            gameDayId: outcome.gameDayId,
                            playerId: outcome.playerId,
                            team: outcome.team,
                        },
                    },
                );
            }
            const { outcomes: playerOutcomes = [], ...playerData } = player;

            // Outcomes arrive newest-first; reverse so the arc reads oldest→newest.
            const actualForm = [...playerOutcomes]
                .reverse()
                .map(({ gameDay: formGameDay, ...formOutcome }) => ({
                    ...formOutcome,
                    gameDay: formGameDay,
                    points: getPlayerPoints(
                        formGameDay.status,
                        formOutcome.team,
                    ),
                }));

            // Left-pad with unplayed sentinels for players newer than formHistory games.
            const paddingCount = Math.max(
                0,
                validatedHistory - actualForm.length,
            );
            const padding = Array.from({ length: paddingCount }, () => ({
                id: 0,
                gameDayId: 0,
                playerId: playerData.id,
                response: null,
                responseInterval: null,
                points: null,
                team: null,
                comment: null,
                pub: null,
                goalie: null,
            }));

            return TeamPlayerSchema.parse({
                ...playerData,
                outcome: {
                    ...outcome,
                    points: getPlayerPoints(gameDay.status, outcome.team),
                },
                form: [...padding, ...actualForm],
            });
        });
    }

    /**
     * Retrieves outcomes by player ID.
     * @param playerId - The ID of the player.
     * @returns A promise that resolves to an array of outcomes.
     * @throws An error if there is a failure.
     */
    async getByPlayer(
        playerId: number,
    ): Promise<(OutcomeType & { points: PointsValue | null })[]> {
        const outcomes = await prisma.outcome.findMany({
            where: {
                playerId: playerId,
            },
            include: {
                gameDay: { select: { status: true } },
            },
        });

        return outcomes.map(({ gameDay, ...outcome }) => ({
            ...outcome,
            points: getPlayerPoints(gameDay.status, outcome.team),
        }));
    }

    /**
     * Retrieves all outcomes for a player across a given year, or all time when
     * year is 0. Also includes game days where the player had no outcome
     * (not invited) and scheduled days where no game took place
     * (status = NoGame) as synthetic entries with null points, so the result
     * is suitable for building a full activity heatmap with no gaps.
     *
     * @param playerId - The ID of the player.
     * @param year - The year to filter by, or 0 for all time.
     * @param fromDate - Optional earliest date (inclusive). Game days before
     * this date are excluded. Useful for filtering to a player's joined date.
     * @param toDate - Optional latest date (inclusive). Game days after this
     * date are excluded. Useful for filtering to a player's finished date.
     * @returns A promise that resolves to outcomes with game days, ordered by
     * game day date ascending, with game day ID as a tiebreaker. No-game days
     * and uninvited game days are represented as synthetic entries with
     * points = null; no-game days have gameDay.status = NoGame.
     */
    async getHistoryByPlayer(
        playerId: number,
        year: number,
        fromDate?: Date,
        toDate?: Date,
    ): Promise<PlayerFormType[]> {
        const {
            playerId: pid,
            year: yr,
            fromDate: from,
            toDate: to,
        } = z
            .object({
                playerId: z.number().int().min(1),
                year: z.union([
                    z.literal(0),
                    z.number().int().min(1900).max(2100),
                ]),
                fromDate: z.date().optional(),
                toDate: z.date().optional(),
            })
            .parse({ playerId, year, fromDate, toDate });

        // All day-boundary arithmetic uses UTC midnight so results are stable
        // across timezones and DST transitions.
        const utcDay = (y: number, m: number, d: number) =>
            new Date(Date.UTC(y, m, d));
        const utcDayOf = (date: Date) =>
            utcDay(
                date.getUTCFullYear(),
                date.getUTCMonth(),
                date.getUTCDate(),
            );
        const utcNextDayOf = (date: Date) =>
            utcDay(
                date.getUTCFullYear(),
                date.getUTCMonth(),
                date.getUTCDate() + 1,
            );

        const yearStart = yr > 0 ? utcDay(yr, 0, 1) : undefined;
        // When both bounds are present, take the later start so neither is silently ignored.
        const startDate =
            yearStart && from
                ? new Date(
                      Math.max(yearStart.getTime(), utcDayOf(from).getTime()),
                  )
                : (yearStart ?? (from ? utcDayOf(from) : undefined));
        const yearEnd = yr > 0 ? utcDay(yr + 1, 0, 1) : undefined;
        // For toDate, convert the inclusive finished date to an exclusive upper bound (next UTC day),
        // then take the earliest of the year end, player finish, and tomorrow (no future game days).
        const finishedEnd = to ? utcNextDayOf(to) : undefined;
        const tomorrow = utcNextDayOf(new Date());
        const candidates = [yearEnd, finishedEnd, tomorrow].filter(
            (d): d is Date => d !== undefined,
        );
        const endDate = new Date(
            Math.min(...candidates.map((d) => d.getTime())),
        );
        // endDate is always defined: candidates always contains tomorrow.
        const dateRange: { gte?: Date; lt: Date } = { lt: endDate };
        if (startDate) dateRange.gte = startDate;
        const dateFilter = { date: dateRange };

        const [rawOutcomes, dateRangeGameDays] = await Promise.all([
            prisma.outcome.findMany({
                where: {
                    playerId: pid,
                    gameDay: { status: { not: 'NoGame' }, ...dateFilter },
                },
                orderBy: [{ gameDay: { date: 'asc' } }, { gameDayId: 'asc' }],
                include: { gameDay: true },
            }),
            gameDayService.getAll({
                fromDate: startDate,
                beforeDate: endDate,
            }),
        ]);

        const outcomes: PlayerFormType[] = rawOutcomes.map((o) => ({
            ...o,
            points: getPlayerPoints(o.gameDay.status, o.team),
        }));
        const noGameDays = dateRangeGameDays.filter((gd) => !isGame(gd.status));
        const allGameDays = dateRangeGameDays.filter((gd) => isGame(gd.status));

        const playedIds = new Set(outcomes.map((o) => o.gameDayId));
        const makeSynthetic = (
            gameDay: (typeof noGameDays)[number],
        ): PlayerFormType => ({
            id: -gameDay.id,
            gameDayId: gameDay.id,
            playerId: pid,
            response: null,
            responseInterval: null,
            points: null,
            team: null,
            comment: null,
            pub: null,
            goalie: null,
            gameDay,
        });

        const synthetic: PlayerFormType[] = [
            ...noGameDays.map(makeSynthetic),
            ...allGameDays
                .filter((gd) => !playedIds.has(gd.id))
                .map(makeSynthetic),
        ];

        return mergeByDate(outcomes, synthetic);
    }

    /**
     * Retrieves the recent points list for a player before a specific game day.
     *
     * Mirrors the legacy `player_recent_game_points` stored procedure:
     * - only outcomes before `gameDayId`
     * - only rows with a team assigned
     * - newest game first
     * - maximum 10 rows
     *
     * @param gameDayId - The current game day ID.
     * @param playerId - The player ID.
     * @returns A promise that resolves to the selected points values.
     * @throws An error if there is a failure.
     */
    async getRecentGamePoints(
        gameDayId: number,
        playerId: number,
    ): Promise<(number | null)[]> {
        const parsed = z
            .object({
                gameDayId: z.number().int().min(1),
                playerId: z.number().int().min(1),
            })
            .parse({ gameDayId, playerId });

        const outcomes = await prisma.outcome.findMany({
            where: {
                gameDayId: {
                    lt: parsed.gameDayId,
                },
                playerId: parsed.playerId,
                team: {
                    not: null,
                },
            },
            orderBy: {
                gameDayId: 'desc',
            },
            take: 10,
            select: {
                team: true,
                gameDay: { select: { status: true } },
            },
        });

        return outcomes.map((outcome) =>
            getPlayerPoints(outcome.gameDay.status, outcome.team),
        );
    }

    /**
     * Calculates a player's recent average for picker logic using the legacy
     * PHP behavior:
     * - use recent game points before `gameDayId`
     * - include at most `history` rows from that list
     * - if fewer than `history` games exist, credit 1.45 points per missing game
     *
     * @param gameDayId - The current game day ID.
     * @param playerId - The player ID.
     * @param history - Number of recent games to consider.
     * @returns A promise resolving to the recent average.
     * @throws An error if there is a failure.
     */
    async getRecentAverage(
        gameDayId: number,
        playerId: number,
        history: number,
    ): Promise<number> {
        const parsed = z
            .object({
                gameDayId: z.number().int().min(1),
                playerId: z.number().int().min(1),
                history: z.number().int().min(1),
            })
            .parse({ gameDayId, playerId, history });

        const points = await this.getRecentGamePoints(
            parsed.gameDayId,
            parsed.playerId,
        );

        let total = 0;
        let count = 0;
        for (const point of points) {
            total += point ?? 0;
            count++;
            if (count === parsed.history) break;
        }

        total += 1.45 * (parsed.history - count);
        return total / parsed.history;
    }

    /**
     * Retrieves the total number of games where a player was assigned a team.
     *
     * Mirrors the legacy `player_games_played` SQL function:
     * - count outcomes where `team` is not null for the given player.
     *
     * @param playerId - The player ID.
     * @returns A promise resolving to the total count.
     * @throws An error if there is a failure.
     */
    async getPlayerGamesPlayed(playerId: number): Promise<number> {
        const parsedPlayerId = z.number().int().min(1).parse(playerId);

        return prisma.outcome.count({
            where: {
                playerId: parsedPlayerId,
                team: {
                    not: null,
                },
            },
        });
    }

    /**
     * Retrieves the total number of games where a player was assigned a team
     * before a specific game day.
     *
     * Use this for historical picker parity where `played` should reflect
     * what was known at picker run-time for that game.
     *
     * @param playerId - The player ID.
     * @param gameDayId - The game day ID used as an exclusive upper bound.
     * @returns A promise resolving to the total count.
     * @throws An error if there is a failure.
     */
    async getPlayerGamesPlayedBeforeGameDay(
        playerId: number,
        gameDayId: number,
    ): Promise<number> {
        const parsed = z
            .object({
                playerId: z.number().int().min(1),
                gameDayId: z.number().int().min(1),
            })
            .parse({ playerId, gameDayId });

        return prisma.outcome.count({
            where: {
                playerId: parsed.playerId,
                team: {
                    not: null,
                },
                gameDayId: {
                    lt: parsed.gameDayId,
                },
            },
        });
    }

    /**
     * Retrieves the number of games played by player ID in the given year,
     * optionally stopping at a given gameDay ID.
     * @param playerId - The ID of the player.
     * @param year - The year to filter by, or zero for all years.
     * @param untilGameDayId - The gameDay ID to stop at (inclusive), or
     * undefined
     * @returns A promise that resolves to the number of games or null.
     * @throws An error if there is a failure.
     */
    async getGamesPlayedByPlayer(
        playerId: number,
        year: number,
        untilGameDayId?: number,
    ): Promise<number> {
        return prisma.outcome.count({
            where: {
                playerId: playerId,
                team: {
                    not: null,
                },
                gameDay: {
                    status: { in: ['AWin', 'BWin', 'Draw'] },
                    ...(year !== 0
                        ? {
                              date: {
                                  gte: new Date(Date.UTC(year, 0, 1)),
                                  lt: new Date(Date.UTC(year + 1, 0, 1)),
                              },
                          }
                        : {}),
                    ...(untilGameDayId
                        ? {
                              id: {
                                  lte: untilGameDayId,
                              },
                          }
                        : {}),
                },
            },
        });
    }

    /**
     * Retrieves the latest game played in a given year.
     * @param year - The year for which to retrieve the latest game.
     * @returns A Promise that resolves to the gameDayId of the latest game
     * played in the given year, or null if no games were played.
     * @throws If there was an error while fetching the latest game.
     */
    async getLatestGamePlayedByYear(year: number): Promise<number | null> {
        const outcomes = await prisma.outcome.findMany({
            where: {
                team: {
                    not: null,
                },
                gameDay: {
                    status: { in: ['AWin', 'BWin', 'Draw'] },
                    ...(year != 0
                        ? {
                              date: {
                                  gte: new Date(Date.UTC(year, 0, 1)),
                                  lt: new Date(Date.UTC(year + 1, 0, 1)),
                              },
                          }
                        : {}),
                },
            },
            orderBy: {
                gameDayId: 'desc',
            },
            take: 1,
        });
        if (outcomes.length === 0) {
            return null;
        }
        return outcomes[0].gameDayId;
    }

    /**
     * Retrieves the win-draw-loss (WDL) statistics for team 'A' based on the bibs each game.
     *
     * @param {Object} params - The parameters for the query.
     * @param {number} [params.year] - The specific year to filter the game days. If not provided, all years are considered.
     * @returns {Promise<WDLType>} A promise that resolves to an object containing the counts of games won, drawn, and lost.
     * @throws Will throw an error if there is an issue fetching the WDL counts.
     */
    async getByBibs({ year }: { year?: number }): Promise<WDLType> {
        const gameDays = await gameDayService.getAll();

        return gameDays.reduce(
            (acc, gameDay) => {
                if (
                    gameDay.bibs !== null &&
                    (gameDay.status === 'AWin' ||
                        gameDay.status === 'BWin' ||
                        gameDay.status === 'Draw') &&
                    (!year || gameDay.year === year)
                ) {
                    if (gameDay.status === 'Draw') {
                        acc.drawn++;
                    } else {
                        const bibsTeamWon =
                            (gameDay.bibs === 'A' &&
                                gameDay.status === 'AWin') ||
                            (gameDay.bibs === 'B' && gameDay.status === 'BWin');
                        if (bibsTeamWon) acc.won++;
                        else acc.lost++;
                    }
                }
                return acc;
            },
            { won: 0, drawn: 0, lost: 0 },
        );
    }

    /**
     * Creates an outcome from validated write input.
     * @param data - Write payload keyed by `gameDayId` and `playerId`.
     * @returns The created outcome row.
     */
    async create(data: OutcomeWriteInput): Promise<OutcomeType> {
        const writeData = OutcomeWriteInputSchema.parse(data);
        const args = OutcomeCreateOneStrictSchema.parse({ data: writeData });
        return prisma.outcome.create(args);
    }

    /**
     * Upserts an outcome by the `(gameDayId, playerId)` composite key.
     * @param data - Write payload keyed by `gameDayId` and `playerId`.
     * @returns The created or updated outcome row.
     */
    async upsert(data: OutcomeWriteInput): Promise<OutcomeType> {
        const writeData = OutcomeWriteInputSchema.parse(data);
        const args = OutcomeUpsertOneStrictSchema.parse({
            where: {
                gameDayId_playerId: {
                    gameDayId: writeData.gameDayId,
                    playerId: writeData.playerId,
                },
            },
            create: writeData,
            update: writeData,
        });
        return prisma.outcome.upsert(args);
    }

    /**
     * Deletes an outcome by its composite key.
     *
     * Not-found deletes (`P2025`) are treated as no-ops.
     *
     * @param gameDayId - The ID of the game day.
     * @param playerId - The ID of the player.
     * @returns Resolves when deletion handling completes.
     * @throws {z.ZodError} If key validation fails.
     * @throws {Error} If Prisma delete fails for reasons other than not-found.
     */
    async delete(gameDayId: number, playerId: number): Promise<void> {
        try {
            const where = OutcomeWhereUniqueInputObjectSchema.parse({
                gameDayId_playerId: {
                    gameDayId: gameDayId,
                    playerId: playerId,
                },
            });

            await prisma.outcome.delete({ where });
        } catch (error) {
            if (isPrismaNotFoundError(error)) {
                return;
            }
            throw error;
        }
    }

    /**
     * Deletes all outcomes.
     * @returns A promise that resolves when all outcomes are deleted.
     */
    async deleteAll(): Promise<void> {
        await prisma.outcome.deleteMany();
    }
}

const outcomeService = new OutcomeService();
export default outcomeService;

