578	        .filter((g) => g._max.gameDayId !== null)
579	        .map((g) => ({ playerId: g.playerId, gameDayId: g._max.gameDayId! }));
580	
581	    if (conditions.length > 0) {
582	        const records = await prisma.playerRecord.findMany({
583	            where: { year, OR: conditions },
584	        });
585	        for (const record of records) {
586	            map[record.playerId] = PlayerRecordWriteInputSchema.parse(record);
587	        }
588	    }
