638	async function calculateYearPlayerRecords(
639	    year: number,
640	    yearOutcomes: OutcomeType[],
641	    yearPlayerRecords: Record<number, Partial<PlayerRecordType>>,
642	    gameDay: GameDayType,
643	    gameDayOutcomes: OutcomeType[],
644	    playerRecords: PlayerRecordType[],
645	    statusById: Map<number, GameDayStatus>,
646	) {
647	    // Start with a list of PlayerRecords, including those for anyone with any
648	    // standing this year. For each one with an outcome this game day, add or
649	    // update the PlayerRecord as appropriate
650	
651	    for (const outcome of gameDayOutcomes) {
652	        yearPlayerRecords[outcome.playerId] = {
653	            ...yearPlayerRecords[outcome.playerId],
654	            ...calculatePlayerRecord(
655	                year,
656	                gameDay,
657	                yearOutcomes,
658	                outcome,
659	                statusById,
660	            ),
661	        };
662	    }
663	
664	    // Update the scores that vary with game day, regardless of whether the
665	    // player played this game (e.g. stalwart score)
666	
667	    const gamesPlayed = await gameDayService.getGamesPlayed(year, gameDay.id);
668	
669	    for (const recordData of Object.values(yearPlayerRecords)) {
670	        recordData.gameDayId = gameDay.id;
671	        recordData.gamesPlayed = gamesPlayed;
672	        if (recordData.played && gamesPlayed > 0) {
673	            recordData.scoreStalwart = Math.round(
674	                (100.0 * recordData.played) / gamesPlayed,
675	            );
676	        }
677	    }
678	
679	    // Calculate the ranks for the set of PlayerRecords
680	    const pointsArray = Object.values(yearPlayerRecords)
681	        .map((r) => r.scorePoints)
682	        .filter((p): p is number => p != null);
683	    pointsArray.sort((a, b) => b - a);
684	
685	    const averagesArray = Object.values(yearPlayerRecords)
686	        .map((r) =>
687	            r.played &&
688	            r.played > 0 &&
689	            r.played >= config.minGamesForAveragesTable
690	                ? r.scoreAverages
691	                : null,
692	        )
693	        .filter((a): a is number => a != null);
694	    averagesArray.sort((a, b) => b - a);
695	
696	    const averagesArrayUnqualified = Object.values(yearPlayerRecords)
697	        .map((r) =>
698	            r.played &&
699	            r.played > 0 &&
700	            r.played < config.minGamesForAveragesTable
701	                ? r.scoreAverages
702	                : null,
703	        )
704	        .filter((a): a is number => a != null);
705	    averagesArrayUnqualified.sort((a, b) => b - a);
706	
707	    const stalwartArray = Object.values(yearPlayerRecords)
708	        .map((r) => r.scoreStalwart)
709	        .filter((s): s is number => s != null);
710	    stalwartArray.sort((a, b) => b - a);
711	
712	    const speedyArray = Object.values(yearPlayerRecords)
713	        .map((r) =>
714	            r.responses && r.responses >= config.minRepliesForSpeedyTable
715	                ? r.scoreSpeedy
716	                : null,
717	        )
718	        .filter((s): s is number => s != null);
719	    speedyArray.sort((a, b) => a - b);
720	
721	    const speedyArrayUnqualified = Object.values(yearPlayerRecords)
722	        .map((r) =>
723	            r.responses && r.responses < config.minRepliesForSpeedyTable
724	                ? r.scoreSpeedy
725	                : null,
726	        )
727	        .filter((s): s is number => s != null);
728	    speedyArrayUnqualified.sort((a, b) => a - b);
729	
730	    const pubArray = Object.values(yearPlayerRecords)
731	        .map((r) => r.scorePub)
732	        .filter((p): p is number => p != null);
733	    pubArray.sort((a, b) => b - a);
734	
735	    const pointsRanks = rankByScore(pointsArray);
736	    const averagesRanks = rankByScore(averagesArray);
737	    const averagesUnqualifiedRanks = rankByScore(averagesArrayUnqualified);
738	    const stalwartRanks = rankByScore(stalwartArray);
739	    const speedyRanks = rankByScore(speedyArray);
740	    const speedyUnqualifiedRanks = rankByScore(speedyArrayUnqualified);
741	    const pubRanks = rankByScore(pubArray);
742	
743	    for (const recordData of Object.values(yearPlayerRecords)) {
744	        if (recordData.scorePoints != null) {
745	            recordData.rankPoints = getRank(
746	                pointsRanks,
747	                recordData.scorePoints,
748	            );
749	        }
750	        if (recordData.scoreAverages != null) {
751	            if (
752	                recordData.played &&
753	                recordData.played >= config.minGamesForAveragesTable
754	            ) {
755	                recordData.rankAverages = getRank(
756	                    averagesRanks,
757	                    recordData.scoreAverages,
758	                );
759	                recordData.rankAveragesUnqualified = null;
760	            } else {
761	                recordData.rankAveragesUnqualified = getRank(
762	                    averagesUnqualifiedRanks,
763	                    recordData.scoreAverages,
764	                );
765	                recordData.rankAverages = null;
766	            }
767	        }
768	        if (recordData.scoreStalwart != null) {
769	            recordData.rankStalwart = getRank(
770	                stalwartRanks,
771	                recordData.scoreStalwart,
772	            );
773	        }
774	        if (recordData.scoreSpeedy != null) {
775	            if (
776	                recordData.responses &&
777	                recordData.responses >= config.minRepliesForSpeedyTable
778	            ) {
779	                recordData.rankSpeedy = getRank(
780	                    speedyRanks,
781	                    recordData.scoreSpeedy,
782	                );
783	                recordData.rankSpeedyUnqualified = null;
784	            } else {
785	                recordData.rankSpeedyUnqualified = getRank(
786	                    speedyUnqualifiedRanks,
787	                    recordData.scoreSpeedy,
788	                );
789	                recordData.rankSpeedy = null;
790	            }
791	        }
792	        if (recordData.scorePub != null) {
793	            recordData.rankPub = getRank(pubRanks, recordData.scorePub);
794	        }
795	    }
796	
797	    // Upsert the PlayerRecords and add them to the overall list
798	
799	    for (const recordData of Object.values(yearPlayerRecords)) {
800	        const playerRecord = await playerRecordService.upsert(
801	            recordData as PlayerRecordWriteInput,
802	        );
803	        playerRecords.push(playerRecord);
804	    }
805	}
806	
807	/**
808	 * Calculates the player record for a specific year and game day based on the
809	 * provided outcomes.
810	 * @param year - The year of the player record.
811	 * @param gameDay - The game day for which the player record is calculated.
812	 * @param yearOutcomes - The outcomes for the entire year.
813	 * @param outcome - The outcome for the specific game day.
814	 * @param statusById - A lookup from game day ID to its status, covering
815	 * every game day referenced by `yearOutcomes`, used to derive each outcome's
816	 * points.
817	 * @returns A promise that resolves to a partial player record object.
818	 */
819	function calculatePlayerRecord(
820	    year: number,
821	    gameDay: GameDayType,
822	    yearOutcomes: OutcomeType[],
823	    outcome: OutcomeType,
824	    statusById: Map<number, GameDayStatus>,
825	): Partial<PlayerRecordType> {
826	    const pointsOf = (o: OutcomeType) => {
827	        const status = statusById.get(o.gameDayId);
828	        if (status === undefined) {
829	            throw new InternalError(
830	                `GameDay ${o.gameDayId} is missing from the status map while computing points for player ${o.playerId}.`,
831	                { details: { gameDayId: o.gameDayId, playerId: o.playerId } },
832	            );
833	        }
834	        return getPlayerPoints(status, o.team ?? null);
835	    };
836	
837	    const playerYearOutcomes = yearOutcomes
838	        .filter(
839	            (o) => o.playerId === outcome.playerId && o.gameDayId <= gameDay.id,
840	        )
841	        .map((o) => ({ outcome: o, points: pointsOf(o) }));
842	    const playerYearRespondedOutcomes = playerYearOutcomes.filter(
843	        ({ outcome: o }) => o.response != null,
844	    );
845	    const playerYearPlayedOutcomes = playerYearOutcomes.filter(
846	        ({ points }) => points != null,
847	    );
848	    const pub = playerYearOutcomes.reduce(
849	        (acc, { outcome: o }) => acc + (o.pub ?? 0),
850	        0,
851	    );
852	    const data: Partial<PlayerRecordType> = {
853	        playerId: outcome.playerId,
854	        year: year,
855	        gameDayId: gameDay.id,
856	        responses: playerYearRespondedOutcomes.length,
857	        points: pointsOf(outcome),
858	        ...{ scorePub: pub > 0 ? pub : null },
859	    };
860	
861	    if (playerYearPlayedOutcomes.length > 0) {
862	        data.played = playerYearPlayedOutcomes.length;
863	        data.won = playerYearPlayedOutcomes.filter(
864	            ({ points }) => points == 3,
865	        ).length;
866	        data.drawn = playerYearPlayedOutcomes.filter(
867	            ({ points }) => points == 1,
868	        ).length;
869	        data.lost = playerYearPlayedOutcomes.filter(
870	            ({ points }) => points == 0,
871	        ).length;
872	    }
873	
874	    if (data.played && data.played > 0) {
875	        const totalPoints = playerYearPlayedOutcomes.reduce(
876	            (acc, { points }) => acc + points!,
877	            0,
878	        );
879	        data.scorePoints = totalPoints;
880	        data.scoreAverages = totalPoints / data.played;
881	    }
882	
883	    const responseIntervals = playerYearOutcomes
884	        .map(({ outcome: o }) => o.responseInterval)
885	        .filter((num): num is number => num != null);
886	
887	    if (responseIntervals.length > 0) {
888	        data.scoreSpeedy =
889	            responseIntervals.reduce((acc, ri) => acc + ri, 0) /
890	            responseIntervals.length;
891	    }
892	
893	    return data;
894	}
