1	import { TableName, TableNameSchema } from 'prisma/zod/schemas';
2	import { PlayerRecordType } from 'prisma/zod/schemas/models/PlayerRecord.schema';
3	
4	import { config } from '@/lib/config';
5	
6	export function getYearName(year: number): string {
7	    return year == 0 ? 'All-time' : year.toString();
8	}
9	
10	/**
11	 * The PlayerRecord rank field(s) a TableName is ranked by: [primary,
12	 * unqualified variant]. `Pick` requires every member to be a real
13	 * PlayerRecordType key, so a future rename of any of these fields fails this
14	 * type rather than silently drifting.
15	 */
16	type RankField = keyof Pick<
17	    PlayerRecordType,
18	    | 'rankPoints'
19	    | 'rankAverages'
20	    | 'rankAveragesUnqualified'
21	    | 'rankStalwart'
22	    | 'rankSpeedy'
23	    | 'rankSpeedyUnqualified'
24	    | 'rankPub'
25	>;
26	
27	export const rankMap: Record<TableName, [RankField, RankField | undefined]> = {
28	    points: ['rankPoints', undefined],
29	    averages: ['rankAverages', 'rankAveragesUnqualified'],
30	    stalwart: ['rankStalwart', undefined],
31	    speedy: ['rankSpeedy', 'rankSpeedyUnqualified'],
32	    pub: ['rankPub', undefined],
33	};
34	
35	/**
36	 * The PlayerRecord score field a TableName ranks by. `Pick` requires every
37	 * member to be a real PlayerRecordType key, so a future rename of any of
38	 * these fields fails this type rather than silently drifting.
39	 */
40	type ScoreField = keyof Pick<
41	    PlayerRecordType,
42	    | 'scorePoints'
43	    | 'scoreAverages'
44	    | 'scoreStalwart'
45	    | 'scoreSpeedy'
46	    | 'scorePub'
47	>;
48	
49	/** Maps a TableName to the PlayerRecord field it ranks by. */
50	export const scoreFieldMap: Record<TableName, ScoreField> = {
51	    points: 'scorePoints',
52	    averages: 'scoreAverages',
53	    stalwart: 'scoreStalwart',
54	    speedy: 'scoreSpeedy',
55	    pub: 'scorePub',
56	};
57	
58	export function ShortTableTitle(table: TableName): string {
59	    return table.charAt(0).toUpperCase() + table.slice(1);
60	}
61	
62	export function TableTitle(table: TableName): string {
63	    switch (table) {
64	        case TableNameSchema.enum.speedy:
65	            return 'Captain Speedy';
66	        case TableNameSchema.enum.stalwart:
67	            return 'Stalwart Standings';
68	        default:
69	            return table.charAt(0).toUpperCase() + table.slice(1) + ' Table';
70	    }
71	}
72	
73	export function QualifiedTableName(table: TableName, year: number): string {
74	    return `${getYearName(year)} ${TableTitle(table)}`;
75	}
76	
77	export function UnqualifiedTableName(table: TableName): string | undefined {
78	    switch (table) {
79	        case TableNameSchema.enum.averages:
80	            return `Played Fewer than ${config.minGamesForAveragesTable} Games`;
81	        case TableNameSchema.enum.speedy:
82	            return `Responded Fewer than ${config.minRepliesForSpeedyTable} Times`;
83	        default:
84	            return undefined;
85	    }
86	}
