368	
369	                return this.sanitizePlayerName(playerWithComputedFields);
370	            },
371	        );
372	    }
373	
374	    /**
375	     * Retrieves all player IDs and logins from the database.
376	     *
377	     * @returns {Promise<string[]>} A promise that resolves to an array of strings containing player IDs and logins.
378	     * @throws Will throw an error if there is an issue fetching the player data.
379	     */
380	    async getAllIdsAndLogins() {
381	        const players = await prisma.player.findMany({
382	            select: {
383	                id: true,
384	                logins: {
385	                    select: {
386	                        login: true,
387	                    },
