389	                        login: 'asc',
390	                    },
391	                },
392	            },
393	        });
394	        const idsAndLogins: string[] = [];
395	
396	        players.forEach((player) => {
397	            idsAndLogins.push(player.id.toString());
398	            player.logins.forEach((login) => {
399	                idsAndLogins.push(login.login);
400	            });
401	        });
402	
403	        return idsAndLogins;
404	    }
405	
406	    /**
407	     * Retrieves the form of a player for a given game day, based on their previous outcomes.
408	     * @param playerId - The ID of the player.
409	     * @param gameDayId - The ID of the game day to consider, or 0 for the latest.
