427	            },
428	            take: history,
429	            include: {
430	                gameDay: true,
431	            },
432	        });
433	
434	        return outcomes.map((outcome) => ({
435	            ...outcome,
436	            points: getPlayerPoints(outcome.gameDay.status, outcome.team),
437	        }));
