442	     * year and/or points value.
443	     *
444	     * @param playerId - The unique identifier of the player.
445	     * @param year - An optional year to limit the search range, or omit for
446	     * any year (backed by PlayerRecord's `year = 0` all-time bucket).
447	     * @param points - An optional points filter: if provided, only game days
448	     * this player earned exactly this many points on will be returned. If
449	     * not, the most recent game day with a decided result will be returned.
450	     * @returns A promise that resolves to the PlayerRecord row for the
451	     * player's latest matching game day, including that game day, or `null`
452	     * if none is found.
453	     * @throws Will propagate any errors encountered during the retrieval
454	     * process.
455	     */
456	    async getLastResult(
457	        playerId: number,
458	        year?: number,
459	        points?: PointsValue,
460	    ): Promise<PlayerLastResultType | null> {
461	        const id = z.coerce.number().int().min(1).parse(playerId);
462	        const validatedPoints = PointsSchema.optional().parse(points);
463	
464	        const record = await prisma.playerRecord.findFirst({
465	            where: {
466	                playerId: id,
467	                year: year ?? 0,
468	                points: validatedPoints ?? { not: null },
469	            },
470	            orderBy: {
