619	     * Builds a hierarchical family tree of players based on the `introducedBy`
620	     * relationship.
621	     *
622	     * Only players who have played at least one game (an outcome with a
623	     * non-null team) are included. Players who have never played are skipped,
624	     * but their place in the introducer chain is preserved: each played
625	     * player's effective parent is the nearest ancestor in the `introducedBy`
626	     * chain who has also played.
627	     *
628	     * After computing effective parents, the tree is further pruned to players
629	     * who either have an effective parent or are themselves the effective
630	     * introducer of at least one other played player. Played players with no
631	     * connection to anyone else are excluded.
632	     *
633	     * A single founder is identified as the first played player with no
634	     * effective parent who is also an effective introducer. Any remaining
635	     * parentless players (orphans) are attached as children of the founder.
636	     *
637	     * If no founder can be identified (e.g. the data contains only circular
638	     * references or no connections at all), an empty virtual root node named
639	     * "Toastboy FC" is returned with no children.
640	     *
641	     * @returns A promise resolving to a single {@link FamilyTreeNodeType} root
642	     * node whose children form the complete introduction tree.
643	     */
644	    async getFamilyTree(): Promise<FamilyTreeNodeType> {
645	        const [allPlayers, playedRows] = await Promise.all([
646	            prisma.player.findMany({
647	                select: {
648	                    id: true,
649	                    name: true,
650	                    anonymous: true,
651	                    introducedBy: true,
652	                },
653	            }),
654	            prisma.outcome.findMany({
655	                where: { team: { not: null } },
656	                select: { playerId: true },
657	                distinct: ['playerId'],
658	            }),
659	        ]);
660	
661	        /** Set of player IDs who have actually played at least one game. */
662	        const playedIds = new Set(playedRows.map((r) => r.playerId));
663	
664	        /**
665	         * Lookup from any player ID to their introducedBy value, used to
666	         * walk up the chain past removed (non-played) players.
667	         */
668	        const introducedByMap = new Map(
669	            allPlayers.map((p) => [p.id, p.introducedBy]),
670	        );
671	
672	        /** Only keep players who have played at least one game. */
673	        const playedPlayers = allPlayers.filter((p) => playedIds.has(p.id));
674	
675	        /**
676	         * For each played player, compute the effective parent: the
677	         * nearest ancestor in the introducer chain who has also played.
678	         */
679	        const effectiveParent = new Map<number, number | null>();
680	        for (const p of playedPlayers) {
681	            let parentId = p.introducedBy;
682	            while (parentId !== null && !playedIds.has(parentId)) {
683	                parentId = introducedByMap.get(parentId) ?? null;
684	            }
685	            effectiveParent.set(p.id, parentId);
686	        }
687	
688	        /**
689	         * Set of played player IDs that are the effective introducer of
690	         * at least one other played player.
691	         */
692	        const introducerIds = new Set(
693	            [...effectiveParent.values()].filter(
694	                (id): id is number => id !== null,
695	            ),
696	        );
697	
698	        /**
699	         * Keep played players who have an effective parent, or who are
700	         * themselves an effective introducer. Excludes played players
701	         * with no connection to anyone else in the tree.
702	         */
703	        const players = playedPlayers.filter(
704	            (p) =>
705	                effectiveParent.get(p.id) !== null || introducerIds.has(p.id),
706	        );
707	
708	        /** Map from player id to their tree node. */
709	        const nodeMap = new Map<number, FamilyTreeNodeType>();
710	        for (const p of players) {
711	            nodeMap.set(p.id, {
712	                id: p.id,
713	                name: this.getDisplayName(p),
714	                children: [],
715	            });
716	        }
717	
718	        /**
719	         * Identify the founder: the played player with no effective
720	         * parent who is also an introducer. Any other orphan players
721	         * are attached under the founder.
722	         */
723	        const orphanIds: number[] = [];
724	        let founderId: number | null = null;
725	        for (const p of players) {
726	            if (effectiveParent.get(p.id) === null) {
727	                if (introducerIds.has(p.id) && founderId === null) {
728	                    founderId = p.id;
729	                } else {
730	                    orphanIds.push(p.id);
731	                }
732	            }
733	        }
734	
735	        /** Build the tree by attaching children to parents. */
736	        for (const p of players) {
737	            const node = nodeMap.get(p.id)!;
738	            const parentId = effectiveParent.get(p.id) ?? null;
739	
740	            if (parentId !== null && nodeMap.has(parentId)) {
741	                nodeMap.get(parentId)!.children.push(node);
742	            }
743	        }
744	
745	        /**
746	         * If a founder was found, attach remaining orphans under them
747	         * and return the founder's node as the tree root.
748	         */
749	        if (founderId !== null) {
750	            const founderNode = nodeMap.get(founderId)!;
751	            for (const id of orphanIds) {
752	                founderNode.children.push(nodeMap.get(id)!);
753	            }
754	            return founderNode;
755	        }
756	
757	        /** Fallback: circular references or no connections — return virtual root. */
758	        return { id: 0, name: 'Toastboy FC', children: [] };
759	    }
