'use server';

import { revalidatePath } from 'next/cache';

import { sendEmailToAllActivePlayers } from '@/actions/sendEmailToAllActivePlayers';
import { requireAdmin } from '@/lib/auth.server';
import { setGameEnabledCore } from '@/lib/core/setGameEnabled';
import { broadcast } from '@/lib/events';
import { SetGameEnabledInputSchema } from '@/types/actions/SetGameEnabled';
import { FootyChannel } from '@/types/FootyChannel';

/**
 * Cancels a game and revalidates related pages.
 *
 * @param rawData - The raw input data to be validated against
 * SetGameEnabledInputSchema
 * @returns A promise that resolves to the cancelled gameDay object
 * @throws {AuthError} When the user is not an admin.
 * @throws Will throw a validation error if rawData does not match
 * SetGameEnabledInputSchema
 */
export async function setGameEnabled(rawData: unknown) {
    await requireAdmin();

    const data = SetGameEnabledInputSchema.parse(rawData);
    const gameDay = await setGameEnabledCore(data, sendEmailToAllActivePlayers);

    revalidatePath('/footy/admin/responses');
    revalidatePath('/footy/fixtures');
    revalidatePath(`/footy/admin/picker`);
    revalidatePath(`/footy/game`);
    broadcast(FootyChannel.Games);

    return gameDay;
}

                            >
                                {renderSortHeader(
                                    'Response time',
                                    'responseTime',
                                )}
                            </Table.Th>
                            <Table.Th
                                aria-sort={
                                    sortKey === 'gamesPlayed'
                                        ? sortDirection === 'asc'
                                            ? 'ascending'
                                            : 'descending'
                                        : 'none'
                                }
                            >
                                {renderSortHeader(
                                    'Total games played',
                                    'gamesPlayed',
                                )}
                            </Table.Th>
                        </Table.Tr>
                    </Table.Thead>
                    <Table.Tbody>{rows}</Table.Tbody>
                </Table>
            </Table.ScrollContainer>
            <Divider
                label="or"
                labelPosition="center"
            />
        </>
    );

    // TODO: New game date component?
    return (
        <Container
            size="lg"
            py="lg"
        >
            <Paper w="100%">
                <Stack gap="md">
                    <Stack
                        align="flex-start"
                        gap="xs"
                    >
                        <Title order={2}>Picker</Title>
                        <Text c="dimmed">
                            Game {gameDay.id}: {formatDate(gameDay.date)}
                        </Text>
                    </Stack>
                    {isGame(gameDay.status) ? picker : null}
                    <Group
                        justify="space-between"
                        align="center"
                        wrap="wrap"
                    >
                        <TextInput
                            aria-label={
                                isGame(gameDay.status)
                                    ? 'Cancellation reason'
                                    : 'Reinstatement reason'
                            }
                            placeholder={
                                isGame(gameDay.status)
                                    ? 'not enough players'
                                    : ''
                            }
                            {...form.getInputProps('reason')}
                            disabled={isSubmitting || isSettingEnabled}
                            flex={1}
                        />
                        <Button
                            type="button"
                            color={isGame(gameDay.status) ? 'red' : 'green'}
                            onClick={handleSetGameEnabled}
                            loading={isSettingEnabled}
                            disabled={isSubmitting || isSettingEnabled}
                            w={{ base: '100%', [actionsBreakpoint]: 150 }}
                        >
                            {isGame(gameDay.status)
                                ? 'Cancel game'
                                : 'Reinstate game'}
                        </Button>
                    </Group>
                </Stack>
            </Paper>
        </Container>
    );
};

type SortKey = 'name' | 'responseTime' | 'gamesPlayed';
type SortDirection = 'asc' | 'desc';

